        ("Add or change cloud API keys", lambda: main(["provider", "secrets", "--open"])),
        ("Update RoConstruct", lambda: main(["update"])),
        ("All commands", lambda: main(["--help"])),
    ]
    while True:
        s = settings()
        print()
        print("RoConstruct %s" % ("- you are %s" % s["user"] if s.get("user") else ""))
