def cmd_brute(a):
    """Portable, resumable compiler and authentic-template sweep."""
    a.action = "status" if a.status else "plan" if a.plan else "run"
    a.name, a.more = "portable-bruteforce-deep" if a.deep else "portable-bruteforce", []
