from roc import chatgpt, clients, libs, providers, worker
from roc.gui_worker import DEFAULTS, LIVE, validate

ROOT = Path(__file__).resolve().parent.parent
ASSETS = ROOT / "roc" / "web"
COMMANDS = {
    "mass": ("Mass match", "Runtime, STL, libraries, analysis and automatic matching", "all"),
    "libs": ("Library match", "Compile registered source recipes and match fingerprints", "all"),
    "analyze": ("Analyze", "Split a client binary into functions", "all"),
    "auto": ("Auto match", "Match deterministic function shapes", "all"),
    "xcopy": ("Cross-copy", "Reuse verified matches across compatible clients", "all"),
    "shapes": ("Shapes", "Inspect the most common unmatched assembly shapes", "all"),
    "repair": ("Repair", "Bounded compiler-backed mutations for partial matches", "one"),
    "check": ("Check source", "Compile sources and compare bytes", "one"),
    "pull": ("Pull sources", "Download shared sources; preserve existing files", "all"),
    "client-fetch": ("Fetch client", "Download binaries and verify registered hashes", "all"),
    "flags": ("Compiler flags", "Find compiler flags from known matches", "one"),
    "doctor": ("Doctor", "Check installation and explain repairs", "none"),
    "model-stats": ("Model stats", "Compare recorded worker performance", "none"),
    "family-stats": ("Family stats", "Inspect family coverage and exact rate", "none"),
    "failures": ("Failures", "Inspect recurring compile and provider failures", "none"),
    "status": ("Server status", "Read server progress and worker leaderboard", "none"),
    "install": ("Install tools", "Download exact compilers; no Ollama or Docker", "optional"),
    "research": ("Research recipes", "Run recorded experiments", "none"),
    "donor": ("Donor reuse", "Reuse verified donor functions", "all"),
    "submit": ("Submit sources", "Submit recovered sources for server verification", "all"),
    "lint": ("Source checks", "Check source and data coverage", "one"),
    "vtables": ("Vtables", "Inspect recovered virtual methods", "one"),
    "daily-stats": ("Daily gains", "Read verified daily results", "none"),
    "agent": ("Agent", "Legacy CLI runs (saved history compatibility)", "none"),
}


def command_args(data):
    name, client = data.get("command"), data.get("client", "")
    if name not in COMMANDS:
        raise ValueError("Unknown command")
    mode = COMMANDS[name][2]
    if mode in ("one", "all") and client not in clients.load() and not (mode == "all" and client == "all"):
        raise ValueError("Choose a registered client")
    args = [name] + ([client] if mode in ("one", "all") else [])
    if name == "mass":
        args = [name, "--client", client]
    if name == "libs":
        from roc import libs
        recipes = str(data.get("recipes", "all")).replace(",", " ").split()
        if not recipes or recipes != ["all"] and any(recipe not in libs.RECIPES for recipe in recipes):
            raise ValueError("Unknown library recipe; use all or registered recipe names")
        args = [name, *recipes, "--client", client]
    if name == "research":
        from roc import research
        action = data.get("research_action", "list")
        if action not in ("list", "plan", "run", "log"):
            raise ValueError("Choose list, plan, run or log")
        args += [action]
        if action in ("plan", "run"):
            recipe = data.get("recipe", "")
            if recipe not in json.loads(research.RECIPES_FILE.read_text(encoding="utf-8")):
                raise ValueError("Choose a registered research recipe")
            args += [recipe]
    if name == "install":
        if data.get("accept_downloads") is not True:
            raise ValueError("Accept compiler downloads before running install")
        args += ["--yes"]
        if client and client != "all":
            if client not in clients.load():
                raise ValueError("Unknown client")
            args += ["--client", client]
    if name in ("check", "repair") and data.get("addr"):
        import re
        addr = data["addr"].lower().removeprefix("0x")
        if not re.fullmatch(r"[0-9a-f]{8}", addr):
            raise ValueError("Address needs eight hex digits")
        args += ([addr] if name == "check" else ["--addr", addr])
    if name == "repair":
        for key, low, high in (("limit", 1, 100000), ("min_score", 0, 100)):
            value = data.get(key, 20 if key == "limit" else 80)
            if type(value) is not int or not low <= value <= high:
                raise ValueError("Invalid %s" % key)
            args += ["--" + key.replace("_", "-"), str(value)]
        if data.get("permute"):
            args += ["--permute"]
    if name == "agent":
        goal, minutes = str(data.get("goal", "")).strip(), data.get("minutes", 120)
        if data.get("cli") not in ("claude", "codex", "opencode"):
            raise ValueError("Choose claude, codex or opencode")
        if not data.get("automatic") and (not goal or len(goal) > 2000):
            raise ValueError("Describe the goal (up to 2000 characters)")
        if type(minutes) is not int or not 1 <= minutes <= 600:
            raise ValueError("Minutes must be 1-600")
        args += [data["cli"]]
        if data.get("automatic"):
            args += ["--automatic"]
            for key, default, low, high in (("workers", 2, 1, 8), ("jobs", 24, 1, 200),
                ("batch_size", 4, 1, 12), ("batch_minutes", 30, 1, 120), ("max_size", 512, 32, 8192)):
                value = data.get(key, default)
                if type(value) is not int or (not (key == "max_size" and value == 0) and not low <= value <= high):
                    raise ValueError("Invalid automatic %s" % key)
                args += ["--" + key.replace("_", "-"), str(value)]
            if data.get("individual") is True:
                args += ["--individual"]
        else:
            args += ["--goal", goal]
        args += ["--minutes", str(minutes)]
        if data.get("model"):
            model = str(data["model"]).strip()
            if not model or len(model) > 120 or model.startswith("-"):
                raise ValueError("Invalid agent model")
            args += ["--model", model]
    return args


class Dashboard:
    def __init__(self, initial=None, directory=None):
        self.directory = directory or ROOT / "work" / "gui"
        self.directory.mkdir(parents=True, exist_ok=True)
        self.lock = threading.RLock()
        self.changed = threading.Condition(self.lock)
        self.jobs = {}
        self.processes = {}
        self.events = collections.deque(maxlen=3000)
        self.sequence = 0
        self.last_save = 0
        self.closed = False
        self.next_agent_start = 0
        self.agent_start_timer = None
        self.token = secrets.token_urlsafe(32)
        self.settings = worker.load_settings()
        self.initial = {**DEFAULTS, "user": self.settings.get("user", ""),
                        "server": self.settings.get("server", ""),
                        "client": self.settings.get("handoff_client", ""),
                        "model": self.settings.get("model", "") or "",
                        "cloud_allowed": bool(self.settings.get("cloud_allowed"))}
        self.worker_token = self.settings.get("token")
        if initial:
            self.initial.update({key: value for key, value in initial.items() if key in DEFAULTS})
            self.worker_token = initial.get("token", self.worker_token)
        self.secret_values = [self.worker_token] if self.worker_token else []
        self.secret_values += [providers.secret(config["key_env"]) for config in providers.providers().values()
                               if providers.key_available(config["key_env"])]
        self.preferences = self.read_json("preferences.json", {"presets": {}, "theme": "dark"})
        for job in self.read_json("history.json", []):
            if job["status"] in ("running", "queued", "paused", "stopping"):
                job["status"] = "interrupted"
                job["ended"] = time.time()
            self.jobs[job["id"]] = job

    def read_json(self, name, default):
        try:
            return json.loads((self.directory / name).read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return default

    def write_json(self, name, data):
        path = self.directory / name
        temp = path.with_suffix(".tmp")
        temp.write_text(json.dumps(data, indent=1), encoding="utf-8")
        temp.replace(path)

    def redact(self, message):
        message = str(message)
        for secret in self.secret_values:
            if secret:
                message = message.replace(secret, "<redacted>")
        return providers.sanitize_prompt(message)

    def save(self):
        # Keep every active job plus the 100 most recent completed runs.
        active = [job for job in self.jobs.values() if job["status"] in ("queued", "running", "paused", "stopping")]
        old = [job for job in self.jobs.values() if job not in active][-100:]
        self.jobs = {job["id"]: job for job in old + active}
        self.write_json("history.json", list(self.jobs.values()))
        self.last_save = time.monotonic()

    def event(self, job_id, kind="log", **fields):
        with self.lock:
            self.sequence += 1
            if "message" in fields:
                fields["message"] = self.redact(fields["message"])
            row = dict(seq=self.sequence, time=time.time(), job=job_id, event=kind, **fields)
            self.events.append(row)
            self.changed.notify_all()
            if job_id:
                path = self.directory / (job_id + ".jsonl")
                if path.exists() and path.stat().st_size > 4 * 1024 * 1024:
                    path.replace(path.with_suffix(".previous.jsonl"))
                with path.open("a", encoding="utf-8") as out:
                    out.write(json.dumps(row) + "\n")
            return row

    def metadata(self):
        registry = clients.load()
        return {"initial": self.initial, "preferences": self.preferences,
                "uri_mode": self.settings.get("uri_interface", "ask"),
                "clients": [{"name": name, "compiler": row.get("compiler", ""),
                             "downloaded": clients.exe_path(name, row).exists(),
                             "analyzed": (ROOT / "work" / name / "functions.jsonl").exists()}
                            for name, row in sorted(registry.items())],
                "providers": [{"name": name, "ready": providers.provider_ready(name),
                               "auth": "chatgpt" if name == "chatgpt" else "cli" if name in ("opencode", "codex", "claude") else "api-key",
                               "models": ([model["slug"] for model in chatgpt.models(refresh=False)]
                                          if name == "chatgpt" else row.get("defaults", []))}
                              for name, row in providers.providers().items()],
                "libraries": libs.NAMES,
                "commands": [{"name": name, "title": row[0], "description": row[1], "target": row[2], "group": "Start here" if name in ("doctor","install","client-fetch","analyze","pull") else "Match and submit" if name in ("mass","auto","xcopy","libs","donor","check","submit") else "Advanced"}
                             for name, row in COMMANDS.items() if name != "agent"],
                "recipes": list(json.loads((ROOT / "research" / "recipes.json").read_text(encoding="utf-8")))}

    def function_history(self, identifier=None, query="", status="", sort="recent", limit=100):
        from roc import telemetry
        local = telemetry.read(identifier, query, status, sort, limit)
        if identifier and not identifier.startswith("server:"):
            return local
        shared = None if identifier else []
        address = self.initial.get("server")
        if address:
            api = worker.Api(address, self.worker_token)
            try:
                params = dict(query=query, status=status, sort=sort, limit=limit)
                if identifier:
                    params["id"] = identifier
                shared = api.call("/v1/function-history?" + urlencode(params), timeout=5)
            except (RuntimeError, OSError, ValueError):
                pass  # Local history stays available when the group server is offline/older.
            finally:
                api.close()
        if identifier:
            return shared
        rows = local + (shared or [])
        if sort in ("unit", "addr"):
            rows.sort(key=lambda row: row.get(sort) or "")
        else:
            rows.sort(key=lambda row: row.get("score", 0) if sort == "score" else
                row.get("score", 0) - row["base_score"] if sort == "gain" and row.get("base_score") is not None else
                0 if sort == "gain" else row.get("started", 0), reverse=True)
        return rows[:limit]

    def snapshot(self, after=0, wait=0):
        with self.changed:
            if wait:
                self.changed.wait_for(lambda: self.sequence > after or self.closed, timeout=wait)
            pending = [row for row in self.events if row["seq"] > after]
            rows = pending[:500]
            return {"jobs": list(self.jobs.values()), "events": rows,
                    "sequence": rows[-1]["seq"] if rows else self.sequence, "more": len(pending) > 500}

    def start(self, data):
        with self.lock:
            if self.closed:
                raise ValueError("Dashboard is shutting down")
            if sum(job["status"] == "queued" for job in self.jobs.values()) >= 20:
                raise ValueError("Queue is full")
            kind = data.get("kind", "command")
            if kind == "worker":
                config = validate(data.get("config", {}))
                args = None
                title = ("Integrator · " if config["lease_mode"] == "native" else "Worker · ") + (config["client"] or "all clients")
            elif kind == "agent_worker":
                args = command_args({**data, "command": "agent", "automatic": not str(data.get("goal", "")).strip()})
                args += ["--continuous"]
                config = {key: data.get(key, default) for key, default in
                    (("cli", "claude"), ("model", ""), ("goal", ""), ("workers", 2), ("jobs", 24), ("minutes", 120),
                     ("batch_size", 4), ("batch_minutes", 30), ("max_size", 512), ("individual", False))}
                config.update(mode=data.get("mode", "automatic"), client=data.get("client", self.initial["client"] or ""),
                              user=str(data.get("user", self.initial["user"])).strip(),
                              server=str(data.get("server", self.initial["server"])).strip())
                if config["client"] not in ("", "all") and config["client"] not in clients.load():
                    raise ValueError("Unknown client")
                args += ["--client", config["client"] or "all"]
                if config["user"] and not worker.USER_RE.fullmatch(config["user"]):
                    raise ValueError("Username needs 2-32 letters, digits, . _ -")
                from roc.link import SERVER_RE
                if config["server"] and not SERVER_RE.fullmatch(config["server"]):
                    raise ValueError("Enter server host:port or http(s) URL")
                if config["server"]:
                    args += ["--server", config["server"]]
                if config["user"]:
                    args += ["--user", config["user"]]
                title = "Agent · " + config["cli"] + " · " + (config["client"] or "all clients")
            elif kind == "command":
                args, config = command_args(data), None
                title = COMMANDS[args[0]][0] + (" · " + data["client"] if data.get("client") else "")
            elif kind == "cpu":
                from roc import tasks
                found = tasks.configs()
                if data.get("config") not in found or "cpu_enabled" not in found[data["config"]][1]:
                    raise ValueError("Choose a local contributor config")
                path, saved = found[data["config"]]
                state_path = path.with_suffix(".status.json")
                state = json.loads(state_path.read_text()) if state_path.exists() else {}
                if state.get("stage") != "stopped" and time.time() - state.get("seen", 0) < 65:
                    raise ValueError("This CPU contributor already runs")
                tasks.cpu_control({"config": data["config"], "action": "on"})
                args, config = ["cpu-worker", "--config", str(path)], {"cpu_config": data["config"]}
                title = "CPU mining · " + saved.get("worker", path.stem)
            else:
                raise ValueError("Unknown job kind")
            job_id = uuid.uuid4().hex[:12]
            job = dict(id=job_id, title=title, kind=kind, args=args, config=config,
                       status="queued", created=time.time(), started=None, ended=None,
                       attempted=0, matched=0, improved=0, failed=0, slots={}, usage={}, revision=0)
            job.update(owner=(config or {}).get("user", self.initial.get("user") or os.environ.get("USERNAME", "local")),
                       pc=socket.gethostname())
            self.jobs[job_id] = job
            self.event(job_id, "state", message="Queued; agent launches are staggered to bound startup memory"
                       if kind == "agent_worker" else
                       "Starting" if kind != "command" else "Queued")
            self.save()
            self.schedule()
            return job_id

    def schedule(self):
        if self.closed:
            return
        agent_wait = max(0, self.next_agent_start - time.monotonic())
        if agent_wait and self.agent_start_timer is None and any(
                row["kind"] == "agent_worker" and row["status"] == "queued" for row in self.jobs.values()):
            def resume_starts():
                with self.lock:
                    self.agent_start_timer = None
                    self.schedule()
            self.agent_start_timer = threading.Timer(agent_wait, resume_starts)
            self.agent_start_timer.daemon = True
            self.agent_start_timer.start()
        command_busy = any(self.jobs[job_id]["kind"] == "command" for job_id in self.processes)
        job = next((row for row in self.jobs.values() if row["status"] == "queued"
                    and (row["kind"] != "command" or not command_busy)
                    and (row["kind"] != "agent_worker" or not agent_wait)), None)
        if job is None:
            return
        job_id = job["id"]
        if job["kind"] == "agent_worker":
            self.next_agent_start = time.monotonic() + max(0, float(self.settings.get("agent_start_interval", 15)))
        argv = [sys.executable, "-u"] + (["-m", "roc.gui_worker"] if job["kind"] == "worker"
                                         else [str(ROOT / "roc.py"), *job["args"]])
        env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUNBUFFERED="1", ROC_GUI_EVENTS="1")
        env.update(ROC_TASK_ID=job_id, ROC_TASK_OWNER=job["owner"])
        if job["kind"] == "agent_worker" and self.worker_token:
            env["ROC_AGENT_SERVER_TOKEN"] = self.worker_token
        try:
            process = subprocess.Popen(argv, cwd=ROOT, env=env, stdin=subprocess.PIPE,
                                       stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,
                                       encoding="utf-8", errors="replace", bufsize=1,
                                       creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
            self.processes[job_id] = process
            job.update(status="running", started=time.time(), pid=process.pid)
            if job["kind"] == "worker":
                process.stdin.write(json.dumps({"config": job["config"], "token": self.worker_token}) + "\n")
                process.stdin.flush()
            else:
                process.stdin.close()
        except OSError as error:
            job.update(status="failed", ended=time.time())
            self.event(job_id, "error", message=str(error))
            self.save()
            self.schedule()
            return
        self.event(job_id, "state", message="Started")
        self.save()
        threading.Thread(target=self.consume, args=(job_id, process), daemon=True).start()
        self.schedule()

    def consume(self, job_id, process):
        started_slots = set()
        for line in process.stdout:
            text = line.rstrip()
            if text.startswith("ROC_EVENT "):
                try:
                    fields = json.loads(text[10:])
                    kind = fields.pop("event")
                except (ValueError, KeyError):
                    kind, fields = "log", {"message": text}
            else:
                kind, fields = "log", {"message": text}
            with self.lock:
                job = self.jobs[job_id]
                if kind in ("job_started", "native_started"):
                    started_slots.add(fields.get("slot"))
                elif kind == "log" and job["kind"] == "worker":
                    fields["startup"] = fields.get("slot") not in started_slots
                if job["kind"] == "agent_worker" and kind != "slot_stopped" and fields.get("slot") is not None:
                    job["slots"].setdefault(str(fields["slot"]), {})  # every loop that reports shows up, even while idle
                if kind == "control":
                    job.update(config=fields["config"], revision=fields["revision"],
                               status="stopping" if fields["stopping"] else "paused" if fields["paused"] else "running")
                    job.pop("pending", None)
                elif kind == "rejected":
                    job.pop("pending", None)
                elif kind == "applied":
                    job["slots"].setdefault(str(fields["slot"]), {}).update(revision=fields["revision"])
                elif kind == "job_started":
                    job["slots"].setdefault(str(fields["slot"]), {}).update(addr=fields["addr"], client=fields["client"],
                                                                          area=fields.get("area", ""), busy=True)
                elif kind in ("native_started", "native_progress", "native_result"):
                    job["slots"].setdefault(str(fields["slot"]), {}).update(
                        file=fields["file"], phase=fields.get("message", "Working"),
                        busy=kind != "native_result", local_exact=fields.get("local_exact", 0))
                    if kind == "native_result":
                        job["attempted"] += 1
                        job["local_exact"] = job.get("local_exact", 0) + fields["local_exact"]
                        job["failed"] += bool(fields.get("error"))
                elif kind == "job_finished":
                    job["attempted"] += 1
                    job["matched"] += fields.get("new_exact", fields["score"] == 100)
                    job["improved"] += fields.get("improved", fields["score"] > fields["previous"]) and fields["score"] != 100
                    job["failed"] += fields["score"] == 0
                    job["slots"].setdefault(str(fields["slot"]), {}).update(busy=False, score=fields["score"])
                elif kind == "benchmark":
                    job["attempted"] = max(job["attempted"], fields.get("completed", 0))
                    job["matched"] = max(job["matched"], fields.get("matched", 0))
                    job["improved"] = max(job["improved"], fields.get("improved", 0))
                    if job["kind"] == "agent_worker":
                        for slot in range(fields.get("workers", 1)):
                            job["slots"].setdefault(str(slot), {})
                elif kind == "slot_stopped":
                    job["slots"].pop(str(fields["slot"]), None)
                elif kind == "usage":
                    job["usage"] = fields
                elif kind == "stage":
                    job["stage"] = fields["message"]
                    if fields.get("task_status") in ("running", "paused") and job["status"] != "stopping":
                        job["status"] = fields["task_status"]
                self.event(job_id, kind, **fields)
                if kind != "log" and (kind in ("control", "rejected") or time.monotonic() - self.last_save >= 1):
                    self.save()
        code = process.wait()
        process.stdout.close()
        if process.stdin and not process.stdin.closed:
            process.stdin.close()
        with self.lock:
            job = self.jobs[job_id]
            job.update(status="cancelled" if job.get("cancelled") else "completed" if code == 0 else "failed",
                       ended=time.time(), exit_code=code, slots={})
            self.processes.pop(job_id, None)
            self.event(job_id, "state", message="%s (exit %s)" % (job["status"].capitalize(), code))
            self.save()
            self.schedule()

    def control(self, data):
        with self.lock:
            job = self.jobs.get(data.get("id"))
            if not job:
                raise ValueError("Unknown job")
            action = data.get("action")
            if action == "restart":
                if job["kind"] not in ("worker", "agent_worker"):
                    raise ValueError("Only worker sessions can restart")
                if job["status"] in ("queued", "running", "paused", "stopping") or job["id"] in self.processes:
                    raise ValueError("Worker already active")
                job.update(status="queued", started=None, ended=None, slots={}, cancelled=False,
                           attempted=0, matched=0, improved=0, failed=0, usage={})
                job.pop("exit_code", None)
                self.event(job["id"], "state", message="Restarting with saved parameters")
                self.save()
                self.schedule()
                return
            if action == "remove":
                if job["status"] in ("queued", "running", "paused", "stopping") or job["id"] in self.processes:
                    raise ValueError("Only finished runs can be removed")
                del self.jobs[job["id"]]
                self.save()
                self.event(None, "state", message="Run removed from history")
                return
            if action == "cancel" and job["status"] == "queued":
                job.update(status="cancelled", ended=time.time())
                self.save()
                return
            process = self.processes.get(job["id"])
            if not process or process.poll() is not None:
                raise ValueError("Job is not running")
            if action == "kill":
                job["cancelled"] = True
                job["status"] = "stopping"
                if os.name == "nt":
                    subprocess.run(["taskkill", "/PID", str(process.pid), "/T", "/F"],
                                   capture_output=True, creationflags=subprocess.CREATE_NO_WINDOW)
                else:
                    process.terminate()
                self.event(job["id"], "state", message="Immediate stop; cloud requests may still bill.")
                return
            if job["kind"] == "agent_worker":
                raise ValueError("Agent workers use Stop immediately; worker/time limits are fixed for this run")
            if job["kind"] == "cpu" and action in ("pause", "resume", "stop"):
                from roc import tasks
                tasks.cpu_control({"config": job["config"]["cpu_config"],
                                    "action": "off" if action == "stop" else action})
                job["status"] = {"pause": "paused", "resume": "running", "stop": "stopping"}[action]
                self.event(job["id"], "state", message="%s requested; active job finishes" % action.capitalize())
                self.save()
                return
            if job["kind"] == "command" and action in ("pause", "resume", "stop"):
                from roc import tasks
                if job["args"][0] not in tasks.COMMANDS:
                    raise ValueError("This command has no cooperative CPU checkpoints")
                tasks.control(job["id"], action)
                job.update(status={"pause": "paused", "resume": "running", "stop": "stopping"}[action])
                if action == "stop":
                    job["cancelled"] = True
                self.event(job["id"], "state", message=action + " requested; applies at next target/compiler boundary")
                self.save()
                return
            if job["kind"] != "worker" or action not in ("pause", "resume", "stop", "update"):
                raise ValueError("Control is supported only for workers")
            if job["status"] == "stopping":
                raise ValueError("Worker is already stopping")
            command = {"action": action, "request": uuid.uuid4().hex[:8]}
            if action == "update":
                changes = data.get("config", {})
                if not isinstance(changes, dict) or set(changes) - LIVE:
                    raise ValueError("Only live settings can change during a session")
                validate(changes, job["config"])
                command["config"] = changes
                job["pending"] = changes
            process.stdin.write(json.dumps(command) + "\n")
            process.stdin.flush()

    def preferences_update(self, data):
        with self.lock:
            if data.get("uri_mode") in ("ask", "terminal", "web"):
                self.settings = worker.save_settings(uri_interface=data["uri_mode"])
            if data.get("theme") in ("light", "dark"):
                self.preferences["theme"] = data["theme"]
            if "preset" in data:
                name = str(data["preset"]).strip()[:60]
                if not name:
                    raise ValueError("Preset name required")
                config = validate(data.get("config", {}), check_model=False)
                self.preferences["presets"][name] = config
            if "agent_preset" in data:
                name = str(data["agent_preset"]).strip()[:60]
                if not name:
                    raise ValueError("Preset name required")
                keys = ("client", "user", "server", "cli", "model", "goal", "mode", "workers", "jobs",
                        "minutes", "batch_size", "batch_minutes", "max_size", "individual")
                # Stored only; command_args validates the values again when an agent starts.
                config = {key: value for key, value in (data.get("config") or {}).items()
                          if key in keys and isinstance(value, (str, int, bool)) and len(str(value)) <= 2000}
                self.preferences.setdefault("agent_presets", {})[name] = config
            self.write_json("preferences.json", self.preferences)

    def shutdown(self):
        with self.lock:
            self.closed = True
            if self.agent_start_timer is not None:
                self.agent_start_timer.cancel()
            self.changed.notify_all()
            for job in self.jobs.values():
                if job["status"] == "queued":
                    job.update(status="cancelled", ended=time.time())
            for job_id in list(self.processes):
                self.control({"id": job_id, "action": "kill"})
            self.save()


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def send(self, code, content, content_type="application/json"):
        if content_type == "application/json":
            content = json.dumps(content).encode()
        try:
            self.send_response(code)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(content)))
            self.send_header("Cache-Control", "no-store")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.send_header("Content-Security-Policy", "default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; frame-ancestors 'none'")
            self.end_headers()
            self.wfile.write(content)
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            # Browser refresh/close can abort a long-poll response. The job
            # remains owned by the dashboard; there is nothing to report.
            return

    def authorized(self):
        host = "127.0.0.1:%d" % self.server.server_port
        if self.headers.get("Host") != host:
            return False
        origin = self.headers.get("Origin")
        if origin and origin != "http://" + host:
            return False
        return secrets.compare_digest(self.headers.get("X-ROC-Token", ""), self.server.dashboard.token)

    def do_GET(self):
        parsed = urlparse(self.path)
        if parsed.path.startswith("/api/"):
            if not self.authorized():
                return self.send(403, {"error": "Dashboard session required"})
            try:
                app = self.server.dashboard
                if parsed.path == "/api/meta":
                    return self.send(200, app.metadata())
                if parsed.path == "/api/state":
                    after = int(parse_qs(parsed.query).get("after", [0])[0])
                    wait = min(1, max(0, float(parse_qs(parsed.query).get("wait", [0])[0])))
                    return self.send(200, app.snapshot(after, wait))
                if parsed.path == "/api/functions":
                    from roc import telemetry
                    query = {key: values[0] for key, values in parse_qs(parsed.query).items()}
                    result = app.function_history(query.get("id"), query.get("query", ""), query.get("status", ""),
                        query.get("sort", "recent"), min(10000, max(1, int(query.get("limit", 100)))))
                    return self.send(200, json.loads(app.redact(json.dumps(result))))
                if parsed.path == "/api/cpu":
                    from roc import tasks
                    selected = parse_qs(parsed.query).get("cluster", [None])[0]
                    return self.send(200, tasks.snapshot(selected))
                if parsed.path == "/api/agent-models":
                    from roc import agent
                    return self.send(200, agent.opencode_models())
                if parsed.path == "/api/agent":
                    from roc import agent
                    return self.send(200, agent.status())
                if parsed.path == "/api/agent-memory":
                    from roc import agent, agent_memory
                    return self.send(200, agent.memory(agent_memory.shared(app.initial.get("server"), app.worker_token), recent_limit=200))
                if parsed.path == "/api/agent-plan":
                    from roc import agent_auto
                    query = parse_qs(parsed.query)
                    profile = query.get("cli", ["claude"])[0] + ":" + (query.get("model", [""])[0] or "default")
                    if query.get("individual", [""])[0] == "true":
                        profile += ":individual"
                    max_size = int(query.get("max_size", [512])[0])
                    if max_size != 0 and not 32 <= max_size <= 8192:
                        raise ValueError("Invalid automatic size limit")
                    client = query.get("client", [""])[0]
                    names = [client] if client and client != "all" else [name for name in clients.load()
                        if (ROOT / "work" / name / "functions.jsonl").exists()]
                    return self.send(200, agent_auto.public_plan(agent_auto.portfolio(names, max_size, profile)))
                if parsed.path == "/api/models":
                    return self.send(200, {"models": worker.draft.ollama_models()})
                if parsed.path == "/api/daily-stats":
                    day = parse_qs(parsed.query).get("date", [""])[0]
                    from roc.reports import day_bounds
                    day, _, _ = day_bounds(day or None)
                    address = app.initial.get("server") or app.settings.get("server")
                    if not address:
                        raise ValueError("Configure a group server first")
                    try:
                        report = worker.Api(address, app.worker_token).call("/v1/daily-stats?date=" + day, timeout=10)
                    except worker.ApiFailure as error:
                        return self.send(502, {"error": str(error)})
                    return self.send(200, report)
                if parsed.path == "/api/log":
                    job_id = parse_qs(parsed.query).get("id", [""])[0]
                    if job_id not in app.jobs:
                        raise ValueError("Unknown job")
                    path = app.directory / (job_id + ".jsonl")
                    previous = path.with_suffix(".previous.jsonl")
                    with app.lock:
                        content = (previous.read_bytes() if previous.exists() else b"") + (path.read_bytes() if path.exists() else b"")
                    return self.send(200, content, "text/plain; charset=utf-8")
            except (ValueError, OSError, RuntimeError) as error:
                return self.send(400, {"error": str(error)})
            return self.send(404, {"error": "Unknown endpoint"})
        files = {"/": "index.html", "/app.js": "app.js", "/style.css": "style.css",
                 "/fonts.css": "fonts.css",
                 # One copy of the brand images, shared with the website in docs/.
                 "/logo.png": ROOT / "docs" / "logo.png",
                 "/favicon.png": ROOT / "docs" / "favicon.png"}
        files.update({"/fonts/" + path.name: "fonts/" + path.name for path in (ASSETS / "fonts").iterdir()
                      if path.suffix == ".woff2"})
        if parsed.path not in files:
            return self.send(404, {"error": "Not found"})
        file = ASSETS / files[parsed.path]
        content_type = mimetypes.guess_type(file.name)[0] or "application/octet-stream"
        self.send(200, file.read_bytes(), content_type + ("; charset=utf-8" if content_type.startswith("text/") else ""))

    def do_POST(self):
        if not self.authorized():
            return self.send(403, {"error": "Dashboard session required"})
        try:
            size = int(self.headers.get("Content-Length", "0"))
            if not 0 < size <= 65536:
                raise ValueError("Invalid request size")
            data = json.loads(self.rfile.read(size))
            if not isinstance(data, dict):
                raise ValueError("JSON object required")
            app = self.server.dashboard
            if self.path == "/api/start":
                return self.send(200, {"id": app.start(data)})
            if self.path == "/api/control":
                app.control(data)
            elif self.path == "/api/cpu-control":
                from roc import tasks
                return self.send(200, tasks.cpu_control(data))
            elif self.path == "/api/roc-control":
                from roc import tasks
                tasks.control(data.get("id", ""), data.get("action"))
            elif self.path == "/api/preferences":
                app.preferences_update(data)
            elif self.path == "/api/provider":
                config = providers.providers().get(data.get("provider"))
                if not config or not config.get("key_env") or not isinstance(data.get("key"), str) or not data["key"].strip():
                    raise ValueError("Provider and key required")
                providers.save_secret(config["key_env"], data["key"].strip())
                app.secret_values.append(data["key"].strip())
            elif self.path in ("/api/agent-session", "/api/agent-setup"):
                from roc import agent
                manual = (agent.open_session(data.get("cli"), data.get("goal"), data.get("model") or None)
                          if self.path == "/api/agent-session" else agent.open_setup(data.get("cli")))
                return self.send(200, {"manual": manual})
            elif self.path == "/api/agent-memory-sync":
                from roc import agent, agent_memory
                return self.send(200, agent.memory(agent_memory.shared(app.initial.get("server"), app.worker_token,
                    app.initial.get("user"), upload=True), recent_limit=200))
            elif self.path == "/api/preview":
                return self.send(200, {"args": command_args(data)})
            elif self.path == "/api/shutdown":
                app.shutdown()
                threading.Thread(target=self.server.shutdown, daemon=True).start()
            else:
                return self.send(404, {"error": "Unknown endpoint"})
            self.send(200, {"ok": True})
        except (ValueError, TypeError, KeyError, OSError, BrokenPipeError, RuntimeError) as error:
            self.send(400, {"error": str(error)})


def serve(port=0, open_browser=True, initial=None, page="overview"):
    app = Dashboard(initial)
    server = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    server.dashboard = app
    url = "http://127.0.0.1:%d/" % server.server_port
    if page == "cpu":
        url += "?page=cpu"
    print("ROC dashboard: " + url, flush=True)
    print("Browser refresh/close keeps jobs running. Ctrl+C stops dashboard and jobs.", flush=True)
    if open_browser:
        webbrowser.open(url + "#" + app.token)
    else:
        # Only explicitly requested headless launches print the session link.
        print("Session link: " + url + "#" + app.token, flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        app.shutdown()
        server.server_close()


if __name__ == "__main__":
    serve()

roc/gui.py.text:
"""Local ROC dashboard; stdlib HTTP, managed subprocesses, no web dependencies."""
import collections
import json
import mimetypes
import os
import secrets
import socket
import subprocess
import sys
import threading
import time
import uuid
import webbrowser
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs, urlencode, urlparse

from roc import chatgpt, clients, libs, providers, worker
from roc.gui_worker import DEFAULTS, LIVE, validate

ROOT = Path(__file__).resolve().parent.parent
ASSETS = ROOT / "roc" / "web"
COMMANDS = {
    "mass": ("Mass match", "Runtime, STL, libraries, analysis and automatic matching", "all"),
    "libs": ("Library match", "Compile registered source recipes and match fingerprints", "all"),
    "analyze": ("Analyze", "Split a client binary into functions", "all"),
    "auto": ("Auto match", "Match deterministic function shapes", "all"),
    "xcopy": ("Cross-copy", "Reuse verified matches across compatible clients", "all"),
    "shapes": ("Shapes", "Inspect the most common unmatched assembly shapes", "all"),
    "repair": ("Repair", "Bounded compiler-backed mutations for partial matches", "one"),
    "check": ("Check source", "Compile sources and compare bytes", "one"),
    "pull": ("Pull sources", "Download shared sources; preserve existing files", "all"),
    "client-fetch": ("Fetch client", "Download binaries and verify registered hashes", "all"),
    "flags": ("Compiler flags", "Find compiler flags from known matches", "one"),
    "doctor": ("Doctor", "Check installation and explain repairs", "none"),
    "model-stats": ("Model stats", "Compare recorded worker performance", "none"),
    "family-stats": ("Family stats", "Inspect family coverage and exact rate", "none"),
    "failures": ("Failures", "Inspect recurring compile and provider failures", "none"),
    "status": ("Server status", "Read server progress and worker leaderboard", "none"),
    "install": ("Install tools", "Download exact compilers; no Ollama or Docker", "optional"),
    "research": ("Research recipes", "Run recorded experiments", "none"),
    "donor": ("Donor reuse", "Reuse verified donor functions", "all"),
    "submit": ("Submit sources", "Submit recovered sources for server verification", "all"),
    "lint": ("Source checks", "Check source and data coverage", "one"),
    "vtables": ("Vtables", "Inspect recovered virtual methods", "one"),
    "daily-stats": ("Daily gains", "Read verified daily results", "none"),
    "agent": ("Agent", "Legacy CLI runs (saved history compatibility)", "none"),
}


def command_args(data):
    name, client = data.get("command"), data.get("client", "")
    if name not in COMMANDS:
        raise ValueError("Unknown command")
    mode = COMMANDS[name][2]
    if mode in ("one", "all") and client not in clients.load() and not (mode == "all" and client == "all"):
        raise ValueError("Choose a registered client")
    args = [name] + ([client] if mode in ("one", "all") else [])
    if name == "mass":
        args = [name, "--client", client]
    if name == "libs":
        from roc import libs
        recipes = str(data.get("recipes", "all")).replace(",", " ").split()
        if not recipes or recipes != ["all"] and any(recipe not in libs.RECIPES for recipe in recipes):
            raise ValueError("Unknown library recipe; use all or registered recipe names")
        args = [name, *recipes, "--client", client]
    if name == "research":
        from roc import research
        action = data.get("research_action", "list")
        if action not in ("list", "plan", "run", "log"):
            raise ValueError("Choose list, plan, run or log")
        args += [action]
        if action in ("plan", "run"):
            recipe = data.get("recipe", "")
            if recipe not in json.loads(research.RECIPES_FILE.read_text(encoding="utf-8")):
                raise ValueError("Choose a registered research recipe")
            args += [recipe]
    if name == "install":
        if data.get("accept_downloads") is not True:
            raise ValueError("Accept compiler downloads before running install")
        args += ["--yes"]
        if client and client != "all":
            if client not in clients.load():
                raise ValueError("Unknown client")
            args += ["--client", client]
    if name in ("check", "repair") and data.get("addr"):
        import re
        addr = data["addr"].lower().removeprefix("0x")
        if not re.fullmatch(r"[0-9a-f]{8}", addr):
            raise ValueError("Address needs eight hex digits")
        args += ([addr] if name == "check" else ["--addr", addr])
    if name == "repair":
        for key, low, high in (("limit", 1, 100000), ("min_score", 0, 100)):
            value = data.get(key, 20 if key == "limit" else 80)
            if type(value) is not int or not low <= value <= high:
                raise ValueError("Invalid %s" % key)
            args += ["--" + key.replace("_", "-"), str(value)]
        if data.get("permute"):
            args += ["--permute"]
    if name == "agent":
        goal, minutes = str(data.get("goal", "")).strip(), data.get("minutes", 120)
        if data.get("cli") not in ("claude", "codex", "opencode"):
            raise ValueError("Choose claude, codex or opencode")
        if not data.get("automatic") and (not goal or len(goal) > 2000):
            raise ValueError("Describe the goal (up to 2000 characters)")
        if type(minutes) is not int or not 1 <= minutes <= 600:
            raise ValueError("Minutes must be 1-600")
        args += [data["cli"]]
        if data.get("automatic"):
            args += ["--automatic"]
            for key, default, low, high in (("workers", 2, 1, 8), ("jobs", 24, 1, 200),
                ("batch_size", 4, 1, 12), ("batch_minutes", 30, 1, 120), ("max_size", 512, 32, 8192)):
                value = data.get(key, default)
                if type(value) is not int or (not (key == "max_size" and value == 0) and not low <= value <= high):
                    raise ValueError("Invalid automatic %s" % key)
                args += ["--" + key.replace("_", "-"), str(value)]
            if data.get("individual") is True:
                args += ["--individual"]
        else:
            args += ["--goal", goal]
        args += ["--minutes", str(minutes)]
        if data.get("model"):
            model = str(data["model"]).strip()
            if not model or len(model) > 120 or model.startswith("-"):
                raise ValueError("Invalid agent model")
            args += ["--model", model]
    return args


class Dashboard:
    def __init__(self, initial=None, directory=None):
        self.directory = directory or ROOT / "work" / "gui"
        self.directory.mkdir(parents=True, exist_ok=True)
        self.lock = threading.RLock()
        self.changed = threading.Condition(self.lock)
        self.jobs = {}
        self.processes = {}
        self.events = collections.deque(maxlen=3000)
        self.sequence = 0
        self.last_save = 0
        self.closed = False
        self.next_agent_start = 0
        self.agent_start_timer = None
        self.token = secrets.token_urlsafe(32)
        self.settings = worker.load_settings()
        self.initial = {**DEFAULTS, "user": self.settings.get("user", ""),
                        "server": self.settings.get("server", ""),
                        "client": self.settings.get("handoff_client", ""),
                        "model": self.settings.get("model", "") or "",
                        "cloud_allowed": bool(self.settings.get("cloud_allowed"))}
        self.worker_token = self.settings.get("token")
        if initial:
            self.initial.update({key: value for key, value in initial.items() if key in DEFAULTS})
            self.worker_token = initial.get("token", self.worker_token)
        self.secret_values = [self.worker_token] if self.worker_token else []
        self.secret_values += [providers.secret(config["key_env"]) for config in providers.providers().values()
                               if providers.key_available(config["key_env"])]
        self.preferences = self.read_json("preferences.json", {"presets": {}, "theme": "dark"})
        for job in self.read_json("history.json", []):
            if job["status"] in ("running", "queued", "paused", "stopping"):
                job["status"] = "interrupted"
                job["ended"] = time.time()
            self.jobs[job["id"]] = job

    def read_json(self, name, default):
        try:
            return json.loads((self.directory / name).read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return default

    def write_json(self, name, data):
        path = self.directory / name
        temp = path.with_suffix(".tmp")
        temp.write_text(json.dumps(data, indent=1), encoding="utf-8")
        temp.replace(path)

    def redact(self, message):
        message = str(message)
        for secret in self.secret_values:
            if secret:
                message = message.replace(secret, "<redacted>")
        return providers.sanitize_prompt(message)

    def save(self):
        # Keep every active job plus the 100 most recent completed runs.
        active = [job for job in self.jobs.values() if job["status"] in ("queued", "running", "paused", "stopping")]
        old = [job for job in self.jobs.values() if job not in active][-100:]
        self.jobs = {job["id"]: job for job in old + active}
        self.write_json("history.json", list(self.jobs.values()))
        self.last_save = time.monotonic()

    def event(self, job_id, kind="log", **fields):
        with self.lock:
            self.sequence += 1
            if "message" in fields:
                fields["message"] = self.redact(fields["message"])
            row = dict(seq=self.sequence, time=time.time(), job=job_id, event=kind, **fields)
            self.events.append(row)
            self.changed.notify_all()
            if job_id:
                path = self.directory / (job_id + ".jsonl")
                if path.exists() and path.stat().st_size > 4 * 1024 * 1024:
                    path.replace(path.with_suffix(".previous.jsonl"))
                with path.open("a", encoding="utf-8") as out:
                    out.write(json.dumps(row) + "\n")
            return row

    def metadata(self):
        registry = clients.load()
        return {"initial": self.initial, "preferences": self.preferences,
                "uri_mode": self.settings.get("uri_interface", "ask"),
                "clients": [{"name": name, "compiler": row.get("compiler", ""),
                             "downloaded": clients.exe_path(name, row).exists(),
                             "analyzed": (ROOT / "work" / name / "functions.jsonl").exists()}
                            for name, row in sorted(registry.items())],
                "providers": [{"name": name, "ready": providers.provider_ready(name),
                               "auth": "chatgpt" if name == "chatgpt" else "cli" if name in ("opencode", "codex", "claude") else "api-key",
                               "models": ([model["slug"] for model in chatgpt.models(refresh=False)]
                                          if name == "chatgpt" else providers.provider_models(name, row))}
                              for name, row in providers.providers().items()],
                "libraries": libs.NAMES,
                "commands": [{"name": name, "title": row[0], "description": row[1], "target": row[2], "group": "Start here" if name in ("doctor","install","client-fetch","analyze","pull") else "Match and submit" if name in ("mass","auto","xcopy","libs","donor","check","submit") else "Advanced"}
                             for name, row in COMMANDS.items() if name != "agent"],
                "recipes": list(json.loads((ROOT / "research" / "recipes.json").read_text(encoding="utf-8")))}

    def function_history(self, identifier=None, query="", status="", sort="recent", limit=100):
        from roc import telemetry
        local = telemetry.read(identifier, query, status, sort, limit)
        if identifier and not identifier.startswith("server:"):
            return local
        shared = None if identifier else []
        address = self.initial.get("server")
        if address:
            api = worker.Api(address, self.worker_token)
            try:
                params = dict(query=query, status=status, sort=sort, limit=limit)
                if identifier:
                    params["id"] = identifier
                shared = api.call("/v1/function-history?" + urlencode(params), timeout=5)
            except (RuntimeError, OSError, ValueError):
                pass  # Local history stays available when the group server is offline/older.
            finally:
                api.close()
        if identifier:
            return shared
        rows = local + (shared or [])
        if sort in ("unit", "addr"):
            rows.sort(key=lambda row: row.get(sort) or "")
        else:
            rows.sort(key=lambda row: row.get("score", 0) if sort == "score" else
                row.get("score", 0) - row["base_score"] if sort == "gain" and row.get("base_score") is not None else
                0 if sort == "gain" else row.get("started", 0), reverse=True)
        return rows[:limit]

    def snapshot(self, after=0, wait=0):
        with self.changed:
            if wait:
                self.changed.wait_for(lambda: self.sequence > after or self.closed, timeout=wait)
            pending = [row for row in self.events if row["seq"] > after]
            rows = pending[:500]
            return {"jobs": list(self.jobs.values()), "events": rows,
                    "sequence": rows[-1]["seq"] if rows else self.sequence, "more": len(pending) > 500}

    def start(self, data):
        with self.lock:
            if self.closed:
                raise ValueError("Dashboard is shutting down")
            if sum(job["status"] == "queued" for job in self.jobs.values()) >= 20:
                raise ValueError("Queue is full")
            kind = data.get("kind", "command")
            if kind == "worker":
                config = validate(data.get("config", {}))
                args = None
                title = ("Integrator · " if config["lease_mode"] == "native" else "Worker · ") + (config["client"] or "all clients")
            elif kind == "agent_worker":
                args = command_args({**data, "command": "agent", "automatic": not str(data.get("goal", "")).strip()})
                args += ["--continuous"]
                config = {key: data.get(key, default) for key, default in
                    (("cli", "claude"), ("model", ""), ("goal", ""), ("workers", 2), ("jobs", 24), ("minutes", 120),
                     ("batch_size", 4), ("batch_minutes", 30), ("max_size", 512), ("individual", False))}
                config.update(mode=data.get("mode", "automatic"), client=data.get("client", self.initial["client"] or ""),
                              user=str(data.get("user", self.initial["user"])).strip(),
                              server=str(data.get("server", self.initial["server"])).strip())
                if config["client"] not in ("", "all") and config["client"] not in clients.load():
                    raise ValueError("Unknown client")
                args += ["--client", config["client"] or "all"]
                if config["user"] and not worker.USER_RE.fullmatch(config["user"]):
                    raise ValueError("Username needs 2-32 letters, digits, . _ -")
                from roc.link import SERVER_RE
                if config["server"] and not SERVER_RE.fullmatch(config["server"]):
                    raise ValueError("Enter server host:port or http(s) URL")
                if config["server"]:
                    args += ["--server", config["server"]]
                if config["user"]:
                    args += ["--user", config["user"]]
                title = "Agent · " + config["cli"] + " · " + (config["client"] or "all clients")
            elif kind == "command":
                args, config = command_args(data), None
                title = COMMANDS[args[0]][0] + (" · " + data["client"] if data.get("client") else "")
            elif kind == "cpu":
                from roc import tasks
                found = tasks.configs()
                if data.get("config") not in found or "cpu_enabled" not in found[data["config"]][1]:
                    raise ValueError("Choose a local contributor config")
                path, saved = found[data["config"]]
                state_path = path.with_suffix(".status.json")
                state = json.loads(state_path.read_text()) if state_path.exists() else {}
                if state.get("stage") != "stopped" and time.time() - state.get("seen", 0) < 65:
                    raise ValueError("This CPU contributor already runs")
                tasks.cpu_control({"config": data["config"], "action": "on"})
                args, config = ["cpu-worker", "--config", str(path)], {"cpu_config": data["config"]}
                title = "CPU mining · " + saved.get("worker", path.stem)
            else:
                raise ValueError("Unknown job kind")
            job_id = uuid.uuid4().hex[:12]
            job = dict(id=job_id, title=title, kind=kind, args=args, config=config,
                       status="queued", created=time.time(), started=None, ended=None,
                       attempted=0, matched=0, improved=0, failed=0, slots={}, usage={}, revision=0)
            job.update(owner=(config or {}).get("user", self.initial.get("user") or os.environ.get("USERNAME", "local")),
                       pc=socket.gethostname())
            self.jobs[job_id] = job
            self.event(job_id, "state", message="Queued; agent launches are staggered to bound startup memory"
                       if kind == "agent_worker" else
                       "Starting" if kind != "command" else "Queued")
            self.save()
            self.schedule()
            return job_id

    def schedule(self):
        if self.closed:
            return
        agent_wait = max(0, self.next_agent_start - time.monotonic())
        if agent_wait and self.agent_start_timer is None and any(
                row["kind"] == "agent_worker" and row["status"] == "queued" for row in self.jobs.values()):
            def resume_starts():
                with self.lock:
                    self.agent_start_timer = None
                    self.schedule()
            self.agent_start_timer = threading.Timer(agent_wait, resume_starts)
            self.agent_start_timer.daemon = True
            self.agent_start_timer.start()
        command_busy = any(self.jobs[job_id]["kind"] == "command" for job_id in self.processes)
        job = next((row for row in self.jobs.values() if row["status"] == "queued"
                    and (row["kind"] != "command" or not command_busy)
                    and (row["kind"] != "agent_worker" or not agent_wait)), None)
        if job is None:
            return
        job_id = job["id"]
        if job["kind"] == "agent_worker":
            self.next_agent_start = time.monotonic() + max(0, float(self.settings.get("agent_start_interval", 15)))
        argv = [sys.executable, "-u"] + (["-m", "roc.gui_worker"] if job["kind"] == "worker"
                                         else [str(ROOT / "roc.py"), *job["args"]])
        env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUNBUFFERED="1", ROC_GUI_EVENTS="1")
        env.update(ROC_TASK_ID=job_id, ROC_TASK_OWNER=job["owner"])
        if job["kind"] == "agent_worker" and self.worker_token:
            env["ROC_AGENT_SERVER_TOKEN"] = self.worker_token
        try:
            process = subprocess.Popen(argv, cwd=ROOT, env=env, stdin=subprocess.PIPE,
                                       stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,
                                       encoding="utf-8", errors="replace", bufsize=1,
                                       creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
            self.processes[job_id] = process
            job.update(status="running", started=time.time(), pid=process.pid)
            if job["kind"] == "worker":
                process.stdin.write(json.dumps({"config": job["config"], "token": self.worker_token}) + "\n")
                process.stdin.flush()
            else:
                process.stdin.close()
        except OSError as error:
            job.update(status="failed", ended=time.time())
            self.event(job_id, "error", message=str(error))
            self.save()
            self.schedule()
            return
        self.event(job_id, "state", message="Started")
        self.save()
        threading.Thread(target=self.consume, args=(job_id, process), daemon=True).start()
        self.schedule()

    def consume(self, job_id, process):
        started_slots = set()
        for line in process.stdout:
            text = line.rstrip()
            if text.startswith("ROC_EVENT "):
                try:
                    fields = json.loads(text[10:])
                    kind = fields.pop("event")
                except (ValueError, KeyError):
                    kind, fields = "log", {"message": text}
            else:
                kind, fields = "log", {"message": text}
            with self.lock:
                job = self.jobs[job_id]
                if kind in ("job_started", "native_started"):
                    started_slots.add(fields.get("slot"))
                elif kind == "log" and job["kind"] == "worker":
                    fields["startup"] = fields.get("slot") not in started_slots
                if job["kind"] == "agent_worker" and kind != "slot_stopped" and fields.get("slot") is not None:
                    job["slots"].setdefault(str(fields["slot"]), {})  # every loop that reports shows up, even while idle
                if kind == "control":
                    job.update(config=fields["config"], revision=fields["revision"],
                               status="stopping" if fields["stopping"] else "paused" if fields["paused"] else "running")
                    job.pop("pending", None)
                elif kind == "rejected":
                    job.pop("pending", None)
                elif kind == "applied":
                    job["slots"].setdefault(str(fields["slot"]), {}).update(revision=fields["revision"])
                elif kind == "job_started":
                    job["slots"].setdefault(str(fields["slot"]), {}).update(addr=fields["addr"], client=fields["client"],
                                                                          area=fields.get("area", ""), busy=True)
                elif kind in ("native_started", "native_progress", "native_result"):
                    job["slots"].setdefault(str(fields["slot"]), {}).update(
                        file=fields["file"], phase=fields.get("message", "Working"),
                        busy=kind != "native_result", local_exact=fields.get("local_exact", 0))
                    if kind == "native_result":
                        job["attempted"] += 1
                        job["local_exact"] = job.get("local_exact", 0) + fields["local_exact"]
                        job["failed"] += bool(fields.get("error"))
                elif kind == "job_finished":
                    job["attempted"] += 1
                    job["matched"] += fields.get("new_exact", fields["score"] == 100)
                    job["improved"] += fields.get("improved", fields["score"] > fields["previous"]) and fields["score"] != 100
                    job["failed"] += fields["score"] == 0
                    job["slots"].setdefault(str(fields["slot"]), {}).update(busy=False, score=fields["score"])
                elif kind == "benchmark":
                    job["attempted"] = max(job["attempted"], fields.get("completed", 0))
                    job["matched"] = max(job["matched"], fields.get("matched", 0))
                    job["improved"] = max(job["improved"], fields.get("improved", 0))
                    if job["kind"] == "agent_worker":
                        for slot in range(fields.get("workers", 1)):
                            job["slots"].setdefault(str(slot), {})
                elif kind == "slot_stopped":
                    job["slots"].pop(str(fields["slot"]), None)
                elif kind == "usage":
                    job["usage"] = fields
                elif kind == "stage":
                    job["stage"] = fields["message"]
                    if fields.get("task_status") in ("running", "paused") and job["status"] != "stopping":
                        job["status"] = fields["task_status"]
                self.event(job_id, kind, **fields)
                if kind != "log" and (kind in ("control", "rejected") or time.monotonic() - self.last_save >= 1):
                    self.save()
        code = process.wait()
        process.stdout.close()
        if process.stdin and not process.stdin.closed:
            process.stdin.close()
        with self.lock:
            job = self.jobs[job_id]
            job.update(status="cancelled" if job.get("cancelled") else "completed" if code == 0 else "failed",
                       ended=time.time(), exit_code=code, slots={})
            self.processes.pop(job_id, None)
            self.event(job_id, "state", message="%s (exit %s)" % (job["status"].capitalize(), code))
            self.save()
            self.schedule()

    def control(self, data):
        with self.lock:
            job = self.jobs.get(data.get("id"))
            if not job:
                raise ValueError("Unknown job")
            action = data.get("action")
            if action == "restart":
                if job["kind"] not in ("worker", "agent_worker"):
                    raise ValueError("Only worker sessions can restart")
                if job["status"] in ("queued", "running", "paused", "stopping") or job["id"] in self.processes:
                    raise ValueError("Worker already active")
                job.update(status="queued", started=None, ended=None, slots={}, cancelled=False,
                           attempted=0, matched=0, improved=0, failed=0, usage={})
                job.pop("exit_code", None)
                self.event(job["id"], "state", message="Restarting with saved parameters")
                self.save()
                self.schedule()
                return
            if action == "remove":
                if job["status"] in ("queued", "running", "paused", "stopping") or job["id"] in self.processes:
                    raise ValueError("Only finished runs can be removed")
                del self.jobs[job["id"]]
                self.save()
                self.event(None, "state", message="Run removed from history")
                return
            if action == "cancel" and job["status"] == "queued":
                job.update(status="cancelled", ended=time.time())
                self.save()
                return
            process = self.processes.get(job["id"])
            if not process or process.poll() is not None:
                raise ValueError("Job is not running")
            if action == "kill":
                job["cancelled"] = True
                job["status"] = "stopping"
                if os.name == "nt":
                    subprocess.run(["taskkill", "/PID", str(process.pid), "/T", "/F"],
                                   capture_output=True, creationflags=subprocess.CREATE_NO_WINDOW)
                else:
                    process.terminate()
                self.event(job["id"], "state", message="Immediate stop; cloud requests may still bill.")
                return
            if job["kind"] == "agent_worker":
                raise ValueError("Agent workers use Stop immediately; worker/time limits are fixed for this run")
            if job["kind"] == "cpu" and action in ("pause", "resume", "stop"):
                from roc import tasks
                tasks.cpu_control({"config": job["config"]["cpu_config"],
                                    "action": "off" if action == "stop" else action})
                job["status"] = {"pause": "paused", "resume": "running", "stop": "stopping"}[action]
                self.event(job["id"], "state", message="%s requested; active job finishes" % action.capitalize())
                self.save()
                return
            if job["kind"] == "command" and action in ("pause", "resume", "stop"):
                from roc import tasks
                if job["args"][0] not in tasks.COMMANDS:
                    raise ValueError("This command has no cooperative CPU checkpoints")
                tasks.control(job["id"], action)
                job.update(status={"pause": "paused", "resume": "running", "stop": "stopping"}[action])
                if action == "stop":
                    job["cancelled"] = True
                self.event(job["id"], "state", message=action + " requested; applies at next target/compiler boundary")
                self.save()
                return
            if job["kind"] != "worker" or action not in ("pause", "resume", "stop", "update"):
                raise ValueError("Control is supported only for workers")
            if job["status"] == "stopping":
                raise ValueError("Worker is already stopping")
            command = {"action": action, "request": uuid.uuid4().hex[:8]}
            if action == "update":
                changes = data.get("config", {})
                if not isinstance(changes, dict) or set(changes) - LIVE:
                    raise ValueError("Only live settings can change during a session")
                validate(changes, job["config"])
                command["config"] = changes
                job["pending"] = changes
            process.stdin.write(json.dumps(command) + "\n")
            process.stdin.flush()

    def preferences_update(self, data):
        with self.lock:
            if data.get("uri_mode") in ("ask", "terminal", "web"):
                self.settings = worker.save_settings(uri_interface=data["uri_mode"])
            if data.get("theme") in ("light", "dark"):
                self.preferences["theme"] = data["theme"]
            if "preset" in data:
                name = str(data["preset"]).strip()[:60]
                if not name:
                    raise ValueError("Preset name required")
                config = validate(data.get("config", {}), check_model=False)
                self.preferences["presets"][name] = config
            if "agent_preset" in data:
                name = str(data["agent_preset"]).strip()[:60]
                if not name:
                    raise ValueError("Preset name required")
                keys = ("client", "user", "server", "cli", "model", "goal", "mode", "workers", "jobs",
                        "minutes", "batch_size", "batch_minutes", "max_size", "individual")
                # Stored only; command_args validates the values again when an agent starts.
                config = {key: value for key, value in (data.get("config") or {}).items()
                          if key in keys and isinstance(value, (str, int, bool)) and len(str(value)) <= 2000}
                self.preferences.setdefault("agent_presets", {})[name] = config
            self.write_json("preferences.json", self.preferences)

    def shutdown(self):
        with self.lock:
            self.closed = True
            if self.agent_start_timer is not None:
                self.agent_start_timer.cancel()
            self.changed.notify_all()
            for job in self.jobs.values():
                if job["status"] == "queued":
                    job.update(status="cancelled", ended=time.time())
            for job_id in list(self.processes):
                self.control({"id": job_id, "action": "kill"})
            self.save()


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def send(self, code, content, content_type="application/json"):
        if content_type == "application/json":
            content = json.dumps(content).encode()
        try:
            self.send_response(code)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(content)))
            self.send_header("Cache-Control", "no-store")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.send_header("Content-Security-Policy", "default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; frame-ancestors 'none'")
            self.end_headers()
            self.wfile.write(content)
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            # Browser refresh/close can abort a long-poll response. The job
            # remains owned by the dashboard; there is nothing to report.
            return

    def authorized(self):
        host = "127.0.0.1:%d" % self.server.server_port
        if self.headers.get("Host") != host:
            return False
        origin = self.headers.get("Origin")
        if origin and origin != "http://" + host:
            return False
        return secrets.compare_digest(self.headers.get("X-ROC-Token", ""), self.server.dashboard.token)

    def do_GET(self):
        parsed = urlparse(self.path)
        if parsed.path.startswith("/api/"):
            if not self.authorized():
                return self.send(403, {"error": "Dashboard session required"})
            try:
                app = self.server.dashboard
                if parsed.path == "/api/meta":
                    return self.send(200, app.metadata())
                if parsed.path == "/api/state":
                    after = int(parse_qs(parsed.query).get("after", [0])[0])
                    wait = min(1, max(0, float(parse_qs(parsed.query).get("wait", [0])[0])))
                    return self.send(200, app.snapshot(after, wait))
                if parsed.path == "/api/functions":
                    from roc import telemetry
                    query = {key: values[0] for key, values in parse_qs(parsed.query).items()}
                    result = app.function_history(query.get("id"), query.get("query", ""), query.get("status", ""),
                        query.get("sort", "recent"), min(10000, max(1, int(query.get("limit", 100)))))
                    return self.send(200, json.loads(app.redact(json.dumps(result))))
                if parsed.path == "/api/cpu":
                    from roc import tasks
                    selected = parse_qs(parsed.query).get("cluster", [None])[0]
                    return self.send(200, tasks.snapshot(selected))
                if parsed.path == "/api/agent-models":
                    from roc import agent
                    return self.send(200, agent.opencode_models())
                if parsed.path == "/api/agent":
                    from roc import agent
                    return self.send(200, agent.status())
                if parsed.path == "/api/agent-memory":
                    from roc import agent, agent_memory
                    return self.send(200, agent.memory(agent_memory.shared(app.initial.get("server"), app.worker_token), recent_limit=200))
                if parsed.path == "/api/agent-plan":
                    from roc import agent_auto
                    query = parse_qs(parsed.query)
                    profile = query.get("cli", ["claude"])[0] + ":" + (query.get("model", [""])[0] or "default")
                    if query.get("individual", [""])[0] == "true":
                        profile += ":individual"
                    max_size = int(query.get("max_size", [512])[0])
                    if max_size != 0 and not 32 <= max_size <= 8192:
                        raise ValueError("Invalid automatic size limit")
                    client = query.get("client", [""])[0]
                    names = [client] if client and client != "all" else [name for name in clients.load()
                        if (ROOT / "work" / name / "functions.jsonl").exists()]
                    return self.send(200, agent_auto.public_plan(agent_auto.portfolio(names, max_size, profile)))
                if parsed.path == "/api/models":
                    return self.send(200, {"models": worker.draft.ollama_models()})
                if parsed.path == "/api/daily-stats":
                    day = parse_qs(parsed.query).get("date", [""])[0]
                    from roc.reports import day_bounds
                    day, _, _ = day_bounds(day or None)
                    address = app.initial.get("server") or app.settings.get("server")
                    if not address:
                        raise ValueError("Configure a group server first")
                    try:
                        report = worker.Api(address, app.worker_token).call("/v1/daily-stats?date=" + day, timeout=10)
                    except worker.ApiFailure as error:
                        return self.send(502, {"error": str(error)})
                    return self.send(200, report)
                if parsed.path == "/api/log":
                    job_id = parse_qs(parsed.query).get("id", [""])[0]
                    if job_id not in app.jobs:
                        raise ValueError("Unknown job")
                    path = app.directory / (job_id + ".jsonl")
                    previous = path.with_suffix(".previous.jsonl")
                    with app.lock:
                        content = (previous.read_bytes() if previous.exists() else b"") + (path.read_bytes() if path.exists() else b"")
                    return self.send(200, content, "text/plain; charset=utf-8")
            except (ValueError, OSError, RuntimeError) as error:
                return self.send(400, {"error": str(error)})
            return self.send(404, {"error": "Unknown endpoint"})
        files = {"/": "index.html", "/app.js": "app.js", "/style.css": "style.css",
                 "/fonts.css": "fonts.css",
                 # One copy of the brand images, shared with the website in docs/.
                 "/logo.png": ROOT / "docs" / "logo.png",
                 "/favicon.png": ROOT / "docs" / "favicon.png"}
        files.update({"/fonts/" + path.name: "fonts/" + path.name for path in (ASSETS / "fonts").iterdir()
                      if path.suffix == ".woff2"})
        if parsed.path not in files:
            return self.send(404, {"error": "Not found"})
        file = ASSETS / files[parsed.path]
        content_type = mimetypes.guess_type(file.name)[0] or "application/octet-stream"
        self.send(200, file.read_bytes(), content_type + ("; charset=utf-8" if content_type.startswith("text/") else ""))

    def do_POST(self):
        if not self.authorized():
            return self.send(403, {"error": "Dashboard session required"})
        try:
            size = int(self.headers.get("Content-Length", "0"))
            if not 0 < size <= 65536:
                raise ValueError("Invalid request size")
            data = json.loads(self.rfile.read(size))
            if not isinstance(data, dict):
                raise ValueError("JSON object required")
            app = self.server.dashboard
            if self.path == "/api/start":
                return self.send(200, {"id": app.start(data)})
            if self.path == "/api/control":
                app.control(data)
            elif self.path == "/api/cpu-control":
                from roc import tasks
                return self.send(200, tasks.cpu_control(data))
            elif self.path == "/api/roc-control":
                from roc import tasks
                tasks.control(data.get("id", ""), data.get("action"))
            elif self.path == "/api/preferences":
                app.preferences_update(data)
            elif self.path == "/api/provider":
                config = providers.providers().get(data.get("provider"))
                if not config or not config.get("key_env") or not isinstance(data.get("key"), str) or not data["key"].strip():
                    raise ValueError("Provider and key required")
                providers.save_secret(config["key_env"], data["key"].strip())
                app.secret_values.append(data["key"].strip())
            elif self.path in ("/api/agent-session", "/api/agent-setup"):
                from roc import agent
                manual = (agent.open_session(data.get("cli"), data.get("goal"), data.get("model") or None)
                          if self.path == "/api/agent-session" else agent.open_setup(data.get("cli")))
                return self.send(200, {"manual": manual})
            elif self.path == "/api/agent-memory-sync":
                from roc import agent, agent_memory
                return self.send(200, agent.memory(agent_memory.shared(app.initial.get("server"), app.worker_token,
                    app.initial.get("user"), upload=True), recent_limit=200))
            elif self.path == "/api/preview":
                return self.send(200, {"args": command_args(data)})
            elif self.path == "/api/shutdown":
                app.shutdown()
                threading.Thread(target=self.server.shutdown, daemon=True).start()
            else:
                return self.send(404, {"error": "Unknown endpoint"})
            self.send(200, {"ok": True})
        except (ValueError, TypeError, KeyError, OSError, BrokenPipeError, RuntimeError) as error:
            self.send(400, {"error": str(error)})


def serve(port=0, open_browser=True, initial=None, page="overview"):
    app = Dashboard(initial)
    server = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    server.dashboard = app
    url = "http://127.0.0.1:%d/" % server.server_port
    if page == "cpu":
        url += "?page=cpu"
    print("ROC dashboard: " + url, flush=True)
    print("Browser refresh/close keeps jobs running. Ctrl+C stops dashboard and jobs.", flush=True)
    if open_browser:
        webbrowser.open(url + "#" + app.token)
    else:
        # Only explicitly requested headless launches print the session link.
        print("Session link: " + url + "#" + app.token, flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        app.shutdown()
        server.server_close()


if __name__ == "__main__":
    serve()

roc/gui_worker.py.base:
"""Controlled worker process. JSON commands on stdin; JSON events on stdout."""
import json
import os
import re
import sys
import threading
import time
from types import SimpleNamespace

from roc import clients, providers, worker, setup

DEFAULTS = dict(client="", server="", user="", model="", workers=1, rounds=4,
                max_size=256, max_tokens=2048, strategy="direct", order="random",
                thinking="auto", reasoning_effort=None, use_revng=False,
                use_remill=True,
                min_score=None, max_score=None, diverse_candidates=1,
                guided_mutations=False, near_repair=False, source_only=False,
                cloud_allowed=False, cloud_concurrency="auto", max_cloud_requests=None,
                max_cloud_tokens=None, max_cloud_cost=None, lease_mode="function",
                unit_name=None, family_id=None, targets=None, library="",
                native_batch_files=40, native_compile_workers=4, native_context="methods")
LIVE = {"workers", "model", "rounds", "max_size", "max_tokens", "strategy", "order",
        "thinking", "reasoning_effort", "use_revng", "use_remill", "min_score", "max_score",
        "diverse_candidates", "guided_mutations", "near_repair", "max_cloud_requests",
        "max_cloud_tokens", "max_cloud_cost", "native_batch_files", "native_compile_workers", "native_context"}


def prepare_clients(config, log):
    """Fetch and analyze the selected Match client before worker loops start."""
    from roc import analyze
    registered = clients.load()
    names = sorted(registered) if not config["client"] else [config["client"]]
    for name in names:
        entry = registered[name]
        if clients.status(name, entry) != "ok":
            log("Match setup: fetching %s client binary." % name)
            if not clients.ensure(name):
                raise SystemExit("Match setup needs %s. Run: roc client-fetch %s" % (name, name))
        build = entry.get("compiler_build")
        if build and build not in setup.compilers():
            log("Match setup: installing %s." % setup.NAMES.get(build, "required compiler"))
            setup.install_compilers(only=[build], assume_yes=True)
            if build not in setup.compilers():
                raise SystemExit("Match setup needs %s. Run: install.cmd" % setup.NAMES.get(build, "the required compiler"))
        functions = clients.ROOT / "work" / name / "functions.jsonl"
        if not functions.exists():
            log("Match setup: analyzing %s." % name)
            analyze.analyze(name, clients.exe_path(name, entry))


def validate(values, base=None, check_model=True):
    if not isinstance(values, dict) or set(values) - set(DEFAULTS):
        raise ValueError("Unknown worker settings")
    config = {**DEFAULTS, **(base or {}), **values}
    for key, low, high in (("workers", 1, 256), ("rounds", 1, 100), ("max_size", 0, 1000000),
                           ("native_batch_files", 1, 1024), ("native_compile_workers", 1, 64),
                           ("max_tokens", 128, 32768), ("diverse_candidates", 1, 16),
                           ("cloud_concurrency", 1, 256)):
        if key in ("workers", "rounds", "max_tokens", "cloud_concurrency") and config[key] == "auto":
            continue
        if type(config[key]) is not int or not low <= config[key] <= high:
            raise ValueError("%s must be %d-%d" % (key, low, high))
    for key in ("min_score", "max_score"):
        if config[key] is not None and (type(config[key]) is not int or not 0 <= config[key] <= 100):
            raise ValueError("%s must be 0-100" % key)
    if config["min_score"] is not None and config["max_score"] is not None and config["min_score"] > config["max_score"]:
        raise ValueError("Minimum score exceeds maximum score")
    for key in ("max_cloud_requests", "max_cloud_tokens", "max_cloud_cost"):
        value = config[key]
        if value is not None and (type(value) not in (int, float) or not 0 < value < float("inf")):
            raise ValueError("%s must be positive" % key)
        if key != "max_cloud_cost" and value is not None and type(value) is not int:
            raise ValueError("%s must be an integer" % key)
    for key, choices in (("strategy", ("auto", "direct", "structured", "reference")),
                          ("order", ("auto", "best", "matched", "unmatched", "easiest", "random")),
                          ("thinking", ("auto", "enabled", "disabled")),
                          ("reasoning_effort", (None, "auto", "low", "medium", "high", "max")),
                          ("lease_mode", ("function", "family", "unit", "native"))):
        if config[key] not in choices:
            raise ValueError("Invalid %s" % key)
    if config["native_context"] not in ("methods", "file"):
        raise ValueError("Invalid native context")
    if config["lease_mode"] == "native":
        if config["client"] not in ("", "2008-06"):
            raise ValueError("Integrator currently supports 2008-06")
        if config["source_only"]:
            raise ValueError("Integrator requires a model")
        config["client"] = "2008-06"
    for key in ("use_revng", "use_remill", "guided_mutations", "near_repair", "source_only", "cloud_allowed"):
        if type(config[key]) is not bool:
            raise ValueError("Invalid %s" % key)
    if not worker.USER_RE.fullmatch(config["user"]):
        raise ValueError("Username needs 2-32 letters, digits, . _ -")
    from roc.link import SERVER_RE
    if not SERVER_RE.fullmatch(config["server"]):
        raise ValueError("Enter server host:port or http(s) URL")
    if config["client"] and config["client"] not in clients.load():
        raise ValueError("Unknown client")
    from roc.libs import NAMES
    if config["library"] and config["library"] not in NAMES:
        raise ValueError("Unknown library")
    if config["lease_mode"] == "unit" and not config["unit_name"]:
        raise ValueError("Unit lease requires a unit name")
    if config["family_id"] and not re.fullmatch(r"[0-9a-f]{24}", config["family_id"]):
        raise ValueError("Family fingerprint needs 24 lowercase hex digits")
    if config["targets"] is not None:
        if not config["client"] or not isinstance(config["targets"], list) or any(
                not isinstance(row, dict) or row.get("client") != config["client"] or
                not re.fullmatch(r"[0-9a-f]{8}", row.get("addr", "")) for row in config["targets"]):
            raise ValueError("Targets need selected client and eight-digit hex addresses")
    model = config["model"]
    if not isinstance(model, str):
        raise ValueError("Invalid model")
    if not config["source_only"]:
        if not model:
            raise ValueError("Select a model or enable source-only")
        if providers.is_cloud(model):
            if not config["cloud_allowed"]:
                raise ValueError("Cloud consent required")
            if check_model and not providers.available(model):
                raise ValueError(providers.credential_hint(model))
        elif check_model and not worker.draft.pick_model(model):
            raise ValueError("Local model unavailable; run roc model")
    return config


class Control:
    def __init__(self, config, emit):
        self.config = config
        self.emit = emit
        self.condition = threading.Condition()
        self.paused = self.stopping = False
        self.revision = 1
        self.budget = providers.CloudBudget(config["max_cloud_requests"], config["max_cloud_tokens"], config["max_cloud_cost"])
        self.cost_known = config["source_only"] or not providers.is_cloud(config["model"]) or providers.has_pricing(config["model"])
        self.applied = {}
        self.started_at = self.last_report = time.monotonic()
        self.completed = self.matched = self.improved = self.errors = 0
        self.started_jobs = {}

    @property
    def workers(self):
        return worker.resolve_workers(self.config["workers"], self.config["model"], self.config["source_only"])

    def command(self, command):
        with self.condition:
            action = command["action"]
            if action == "update":
                if set(command["config"]) - LIVE:
                    raise ValueError("These settings need a new session")
                self.config = validate(command["config"], self.config)
                if not self.config["source_only"] and providers.is_cloud(self.config["model"]) and not providers.has_pricing(self.config["model"]):
                    self.cost_known = False
                with self.budget._lock:
                    self.budget.max_requests = self.config["max_cloud_requests"]
                    self.budget.max_tokens = self.config["max_cloud_tokens"]
                    self.budget.max_cost = self.config["max_cloud_cost"]
                self.revision += 1
            elif action == "pause":
                self.paused = True
            elif action == "resume":
                self.paused = False
            elif action == "stop":
                self.stopping = True
            else:
                raise ValueError("Unknown control action")
            self.condition.notify_all()
            self.emit("control", config=self.config, revision=self.revision,
                      paused=self.paused, stopping=self.stopping, request=command.get("request"))

    def before_lease(self, slot):
        with self.condition:
            while self.paused and not self.stopping and slot < self.workers:
                self.condition.wait()
            if self.stopping or slot >= self.workers:
                return None
            if self.applied.get(slot) != self.revision:
                self.applied[slot] = self.revision
                self.emit("applied", slot=slot, revision=self.revision)
            return dict(self.config)

    def wait(self, seconds):
        with self.condition:
            if not self.stopping:
                self.condition.wait(seconds)

    def started(self, slot, job):
        with self.condition:
            self.started_jobs[slot] = time.monotonic()
        self.emit("job_started", slot=slot, client=job["client"], addr=job["addr"],
                  unit=job.get("unit"), size=job.get("size"), previous=job.get("score", 0))

    def finished(self, slot, job, score):
        with self.condition:
            now = time.monotonic()
            self.completed += 1
            receipt = job.get("receipt") or {}
            gain = bool(receipt.get("verified") and receipt.get("improved")) if "receipt" in job else score > job.get("score", 0)
            self.matched += gain and score == 100
            self.improved += gain and score != 100
            self.emit("job_finished", slot=slot, client=job["client"], addr=job["addr"], score=score,
                      unit=job.get("unit"), size=job.get("size"), previous=job.get("score", 0),
                      new_exact=gain and score == 100, improved=gain,
                      seconds=round(now - self.started_jobs.pop(slot, now), 1))
            if now - self.last_report >= 30:
                self.emit("benchmark", workers=self.workers, completed=self.completed,
                          matched=self.matched, improved=self.improved, errors=self.errors,
                          per_minute=round(self.completed * 60 / max(now - self.started_at, 1), 1))
                self.last_report = now
        with self.budget._lock:
            self.emit("usage", requests=self.budget.requests, tokens=self.budget.tokens,
                      cost=self.budget.cost if self.cost_known else None)
            exhausted = any(limit is not None and used >= limit for used, limit in (
                (self.budget.requests, self.budget.max_requests),
                (self.budget.tokens, self.budget.max_tokens), (self.budget.cost, self.budget.max_cost)))
        if exhausted:
            self.emit("log", slot=slot, message="Cloud budget cap reached; finishing session.")
            self.command({"action": "stop"})


def native_loop(config, control, emit):
    """Native integration: each pass lets the model edit native files that define waiting exact targets, submits
    locally proven edits as one verified batch; discovery continues while the server verifies."""
    from roc import integration, native_sweep, research
    spec = json.loads(json.dumps(research.recipes()["native-model-2008"]))
    worker.save_settings(user=config["user"], server=config["server"])
    emit("log", slot=0, message="Startup: syncing accepted native baseline (unchanged overlays are reused)")
    integration.command(SimpleNamespace(action="sync", server=config["server"], user=config["user"], token=None))
    emit("log", slot=0, message="Startup complete: selecting exact mined targets for parallel integration")
    def native_event(kind, **fields):
        emit(kind, **fields)
        if fields.get("error_category") in ("provider_auth", "cloud_budget"):
            emit("error", slot=fields["slot"], message="Provider unavailable; session stopped. " + fields.get("error", ""))
            control.command({"action": "stop"})

    tried = set()
    pending = set()
    def refresh_pending():
        if not pending:
            return False
        api = worker.Api(config["server"], worker.load_settings().get("token"))
        advanced = False
        try:
            for identifier in list(pending):
                for job in api.call("/v1/integration?id=" + identifier)["jobs"]:
                    if job["state"] not in ("accepted", "rejected", "failed"):
                        continue
                    pending.remove(identifier)
                    credits = (job.get("receipt") or {}).get("credits", 0) if job["state"] == "accepted" else 0
                    control.matched += credits
                    advanced |= job["state"] == "accepted"
                    emit("native_accepted" if credits else "log", credits=credits,
                         message="Native batch %s: %s · %d new server verified" % (identifier[:8], job["state"], credits))
            emit("benchmark", workers=control.workers, completed=control.completed,
                 matched=control.matched, improved=0, errors=control.errors)
        except worker.ApiFailure:
            pass
        finally:
            api.close()
        return advanced
    while not control.stopping:
        current = control.before_lease(0)
        if current is None:
            break
        refresh_pending()
        for slot in range(control.workers):
            emit("applied", slot=slot, revision=control.revision)
        emit("stage", message="Integrator: %d AI workers · %d compilers · up to %d files per batch" % (
            control.workers, current["native_compile_workers"], current["native_batch_files"]))
        spec["native_sweep"].update(llm=current["model"], model=current["model"],
            rounds=3 if current["rounds"] == "auto" else current["rounds"], wait=False, exclude_files=sorted(tried),
            max_files=current["native_batch_files"], context=current["native_context"],
            compile_workers=current["native_compile_workers"],
            provider_options={"allow_cloud": current["cloud_allowed"], "budget": control.budget,
                "gate": providers.CloudGate(control.workers if current["cloud_concurrency"] == "auto" else current["cloud_concurrency"]),
                "max_tokens": 3072 if current["max_tokens"] == "auto" else current["max_tokens"],
                "thinking": current["thinking"], "reasoning_effort": current["reasoning_effort"] if current["reasoning_effort"] not in (None, "auto") else
                    ("low" if current["model"].startswith(("codex:", "claude:")) else None),
                "event": native_event,
                "before_request": lambda: control.before_lease(0) is not None})
        try:
            summary = native_sweep.run(spec, "native-model-2008", server=config["server"] or None, jobs=control.workers,
                                       log=lambda message: emit("log", slot=0, message=str(message)))
        except worker.ApiFailure as error:
            emit("log", slot=0, message="Server temporarily unavailable; proposals saved. Retry in 30s: " + str(error))
            control.wait(30)
            continue
        except (Exception, SystemExit) as error:  # noqa: BLE001 - report and stop like a worker slot
            emit("error", slot=0, message=str(error))
            raise
        emit("log", slot=0, message="native pass: %s, %s local exact, %s verified" % (
            summary.get("state"), summary.get("local_exact", 0), summary.get("new_verified", 0)))
        tried.update(summary.get("files_tried", []))
        if summary.get("job"):
            pending.add(summary["job"])
        control.completed += len(summary.get("files_tried", []))
        control.matched += summary.get("new_verified", 0)
        emit("benchmark", workers=control.workers, completed=control.completed,
             matched=control.matched, improved=0, errors=control.errors)
        with control.budget._lock:
            emit("usage", requests=control.budget.requests, tokens=control.budget.tokens,
                 cost=control.budget.cost if control.cost_known else None)
            exhausted = any(limit is not None and used >= limit for used, limit in (
                (control.budget.requests, control.budget.max_requests),
                (control.budget.tokens, control.budget.max_tokens), (control.budget.cost, control.budget.max_cost)))
        if exhausted:
            emit("log", slot=0, message="Cloud budget cap reached; finishing session.")
            control.command({"action": "stop"})
        if not summary.get("files_tried"):
            emit("stage", message="No fresh native targets; staying active, checking for new evidence every 30s")
            signature = None
            while not control.stopping:
                if refresh_pending():
                    tried.clear()
                    break
                api = worker.Api(current["server"], worker.load_settings().get("token"))
                try:
                    status = next((row for row in api.call("/v1/status")["clients"] if row["client"] == "2008-06"), {})
                    changed = (status.get("matched"), status.get("integrated"), status.get("functions"), control.revision)
                    if signature is not None and changed != signature:
                        tried.clear()
                        break
                    signature = changed
                except worker.ApiFailure:
                    pass  # Keep local proofs while the shared service recovers.
                finally:
                    api.close()
                control.wait(30)
    for slot in range(control.workers):
        emit("slot_stopped", slot=slot)


def main(initial=None, receive_commands=True):
    initial = initial or json.loads(sys.stdin.readline())
    if not receive_commands:
        initial["terminal"] = True
    initial["config"] = validate(initial["config"])
    if initial["config"].get("lease_mode") == "native" and not os.environ.get("ROC_INTEGRATOR_PRIVATE"):
        from roc import integrator
        return integrator.run_private(initial, receive_commands)
    output_lock = threading.Lock()

    def emit(event, **fields):
        with output_lock:
            if initial.get("terminal"):
                slot = "w%d" % (fields["slot"] + 1) if "slot" in fields else "roc"
                if event == "native_result":
                    print("[%s] %s +%d local exact (awaiting verification) | %.1fs%s" % (
                        slot, fields["file"], fields["local_exact"], fields["seconds"],
                        " | " + fields["error"] if fields.get("error") else ""), flush=True)
                elif event == "native_started":
                    print("[%s] %s | baseline" % (slot, fields["file"]), flush=True)
                elif event == "native_progress":
                    if "Requesting" in fields["message"] or "new exact" in fields["message"]:
                        print("[%s] %s | %s" % (slot, fields["file"], fields["message"]), flush=True)
                elif event in ("log", "error", "stage", "native_accepted"):
                    print("[%s] %s" % (slot, fields.get("message", "")), flush=True)
            else:
                print("ROC_EVENT " + json.dumps(dict(event=event, **fields)), flush=True)

    config = validate(initial["config"])
    control = Control(config, emit)
    emit("control", config=config, revision=1, paused=False, stopping=False)
    emit("log", slot=0, message="Startup: checking installed client binary, historical compiler and analysis")
    prepare_clients(config, lambda message: emit("log", slot=0, message=message))
    emit("log", slot=0, message="Startup: client dependencies ready")

    def receive():
        for line in sys.stdin:
            try:
                control.command(json.loads(line))
            except (ValueError, KeyError, TypeError) as error:
                emit("rejected", message=str(error))
        control.command({"action": "stop"})

    if receive_commands:
        threading.Thread(target=receive, daemon=True).start()
    shared_examples, shared_sources = {}, {}
    family_state, family_lock = {"id": config["family_id"]}, threading.Lock()
    gate = providers.CloudGate(control.workers if config["cloud_concurrency"] == "auto" else config["cloud_concurrency"])
    threads, failures = {}, []

    def run_slot(slot):
        with control.condition:
            current = dict(control.config)
        options = {key: value for key, value in current.items() if key not in
                   ("workers", "client", "max_cloud_requests", "max_cloud_tokens", "max_cloud_cost", "cloud_concurrency",
                    "native_batch_files", "native_compile_workers", "native_context")}
        options.update(token=initial.get("token"), only=[current["client"]] if current["client"] else None,
                       model=current["model"] or None, forever=True, cloud_budget=control.budget, cloud_gate=gate,
                       examples_cache=shared_examples, source_cache=shared_sources,
                       family_state=family_state, family_lock=family_lock, control=control, slot=slot,
                       log=lambda message: emit("log", slot=slot, message=str(message)))
        try:
            from roc import telemetry
            telemetry.local.emit = lambda event, **fields: emit(event, slot=slot, **fields)
            worker.run(**options)
        except (Exception, SystemExit) as error:
            failures.append(error)
            with control.condition:
                control.errors += 1
            emit("error", slot=slot, message=str(error))
            control.command({"action": "stop"})
        finally:
            emit("slot_stopped", slot=slot)

    worker.keep_awake()
    if config["lease_mode"] == "native":
        native_loop(config, control, emit)
        return
    while True:
        with control.condition:
            if not control.stopping:
                for slot in range(control.workers):
                    if slot not in threads or not threads[slot].is_alive():
                        threads[slot] = threading.Thread(target=run_slot, args=(slot,), daemon=True)
                        threads[slot].start()
            if control.stopping and not any(thread.is_alive() for thread in threads.values()):
                break
            control.condition.wait(0.3)
    if failures:
        raise SystemExit(1)


if __name__ == "__main__":
    main()

roc/gui_worker.py.text:
"""Controlled worker process. JSON commands on stdin; JSON events on stdout."""
import json
import os
import re
import sys
import threading
import time
from types import SimpleNamespace

from roc import clients, providers, worker, setup

DEFAULTS = dict(client="", server="", user="", model="", workers=1, rounds=4,
                max_size=256, max_tokens=2048, strategy="direct", order="random",
                thinking="auto", reasoning_effort=None, use_revng=False,
                use_remill=True,
                min_score=None, max_score=None, diverse_candidates=1,
                guided_mutations=False, near_repair=False, source_only=False,
                cloud_allowed=False, cloud_concurrency="auto", max_cloud_requests=None,
                max_cloud_tokens=None, max_cloud_cost=None, lease_mode="function",
                unit_name=None, family_id=None, targets=None, library="",
                native_batch_files=40, native_compile_workers="auto", native_context="methods", native_generation="auto", native_compile_batch=4)
LIVE = {"workers", "model", "rounds", "max_size", "max_tokens", "strategy", "order",
        "thinking", "reasoning_effort", "use_revng", "use_remill", "min_score", "max_score",
        "diverse_candidates", "guided_mutations", "near_repair", "max_cloud_requests",
        "max_cloud_tokens", "max_cloud_cost", "native_batch_files", "native_compile_workers", "native_context", "native_generation", "native_compile_batch"}


def prepare_clients(config, log):
    """Fetch and analyze the selected Match client before worker loops start."""
    from roc import analyze
    registered = clients.load()
    names = sorted(registered) if not config["client"] else [config["client"]]
    for name in names:
        entry = registered[name]
        if clients.status(name, entry) != "ok":
            log("Match setup: fetching %s client binary." % name)
            if not clients.ensure(name):
                raise SystemExit("Match setup needs %s. Run: roc client-fetch %s" % (name, name))
        build = entry.get("compiler_build")
        if build and build not in setup.compilers():
            log("Match setup: installing %s." % setup.NAMES.get(build, "required compiler"))
            setup.install_compilers(only=[build], assume_yes=True)
            if build not in setup.compilers():
                raise SystemExit("Match setup needs %s. Run: install.cmd" % setup.NAMES.get(build, "the required compiler"))
        functions = clients.ROOT / "work" / name / "functions.jsonl"
        if not functions.exists():
            log("Match setup: analyzing %s." % name)
            analyze.analyze(name, clients.exe_path(name, entry))


def validate(values, base=None, check_model=True):
    if not isinstance(values, dict) or set(values) - set(DEFAULTS):
        raise ValueError("Unknown worker settings")
    config = {**DEFAULTS, **(base or {}), **values}
    for key, low, high in (("workers", 1, 256), ("rounds", 1, 100), ("max_size", 0, 1000000),
                           ("native_batch_files", 1, 1024), ("native_compile_workers", 1, 64),
                           ("native_compile_batch", 1, 32),
                           ("max_tokens", 128, 32768), ("diverse_candidates", 1, 16),
                           ("cloud_concurrency", 1, 256)):
        if key in ("workers", "rounds", "max_tokens", "cloud_concurrency", "native_compile_workers") and config[key] == "auto":
            continue
        if type(config[key]) is not int or not low <= config[key] <= high:
            raise ValueError("%s must be %d-%d" % (key, low, high))
    for key in ("min_score", "max_score"):
        if config[key] is not None and (type(config[key]) is not int or not 0 <= config[key] <= 100):
            raise ValueError("%s must be 0-100" % key)
    if config["min_score"] is not None and config["max_score"] is not None and config["min_score"] > config["max_score"]:
        raise ValueError("Minimum score exceeds maximum score")
    for key in ("max_cloud_requests", "max_cloud_tokens", "max_cloud_cost"):
        value = config[key]
        if value is not None and (type(value) not in (int, float) or not 0 < value < float("inf")):
            raise ValueError("%s must be positive" % key)
        if key != "max_cloud_cost" and value is not None and type(value) is not int:
            raise ValueError("%s must be an integer" % key)
    for key, choices in (("strategy", ("auto", "direct", "structured", "reference")),
                          ("order", ("auto", "best", "matched", "unmatched", "easiest", "random")),
                          ("thinking", ("auto", "enabled", "disabled")),
                          ("reasoning_effort", (None, "auto", "low", "medium", "high", "max")),
                          ("lease_mode", ("function", "family", "unit", "native"))):
        if config[key] not in choices:
            raise ValueError("Invalid %s" % key)
    if config["native_context"] not in ("methods", "file"):
        raise ValueError("Invalid native context")
    if config["native_generation"] not in ("auto", "edits", "method"):
        raise ValueError("Invalid native generation mode")
    if config["lease_mode"] == "native":
        if config["client"] not in ("", "2008-06"):
            raise ValueError("Integrator currently supports 2008-06")
        if config["source_only"]:
            raise ValueError("Integrator requires a model")
        config["client"] = "2008-06"
    for key in ("use_revng", "use_remill", "guided_mutations", "near_repair", "source_only", "cloud_allowed"):
        if type(config[key]) is not bool:
            raise ValueError("Invalid %s" % key)
    if not worker.USER_RE.fullmatch(config["user"]):
        raise ValueError("Username needs 2-32 letters, digits, . _ -")
    from roc.link import SERVER_RE
    if not SERVER_RE.fullmatch(config["server"]):
        raise ValueError("Enter server host:port or http(s) URL")
    if config["client"] and config["client"] not in clients.load():
        raise ValueError("Unknown client")
    from roc.libs import NAMES
    if config["library"] and config["library"] not in NAMES:
        raise ValueError("Unknown library")
    if config["lease_mode"] == "unit" and not config["unit_name"]:
        raise ValueError("Unit lease requires a unit name")
    if config["family_id"] and not re.fullmatch(r"[0-9a-f]{24}", config["family_id"]):
        raise ValueError("Family fingerprint needs 24 lowercase hex digits")
    if config["targets"] is not None:
        if not config["client"] or not isinstance(config["targets"], list) or any(
                not isinstance(row, dict) or row.get("client") != config["client"] or
                not re.fullmatch(r"[0-9a-f]{8}", row.get("addr", "")) for row in config["targets"]):
            raise ValueError("Targets need selected client and eight-digit hex addresses")
    model = config["model"]
    if not isinstance(model, str):
        raise ValueError("Invalid model")
    if not config["source_only"]:
        if not model:
            raise ValueError("Select a model or enable source-only")
        if providers.is_cloud(model):
            if not config["cloud_allowed"]:
                raise ValueError("Cloud consent required")
            if check_model and not providers.available(model):
                raise ValueError(providers.credential_hint(model))
        elif check_model and not worker.draft.pick_model(model):
            raise ValueError("Local model unavailable; run roc model")
    return config


class Control:
    def __init__(self, config, emit):
        self.config = config
        self.emit = emit
        self.condition = threading.Condition()
        self.paused = self.stopping = False
        self.revision = 1
        self.budget = providers.CloudBudget(config["max_cloud_requests"], config["max_cloud_tokens"], config["max_cloud_cost"])
        self.cost_known = config["source_only"] or not providers.is_cloud(config["model"]) or providers.has_pricing(config["model"])
        self.applied = {}
        self.started_at = self.last_report = time.monotonic()
        self.completed = self.matched = self.improved = self.errors = 0
        self.started_jobs = {}

    @property
    def workers(self):
        return worker.resolve_workers(self.config["workers"], self.config["model"], self.config["source_only"])

    def command(self, command):
        with self.condition:
            action = command["action"]
            if action == "update":
                if set(command["config"]) - LIVE:
                    raise ValueError("These settings need a new session")
                self.config = validate(command["config"], self.config)
                if not self.config["source_only"] and providers.is_cloud(self.config["model"]) and not providers.has_pricing(self.config["model"]):
                    self.cost_known = False
                with self.budget._lock:
                    self.budget.max_requests = self.config["max_cloud_requests"]
                    self.budget.max_tokens = self.config["max_cloud_tokens"]
                    self.budget.max_cost = self.config["max_cloud_cost"]
                self.revision += 1
            elif action == "pause":
                self.paused = True
            elif action == "resume":
                self.paused = False
            elif action == "stop":
                self.stopping = True
            else:
                raise ValueError("Unknown control action")
            self.condition.notify_all()
            self.emit("control", config=self.config, revision=self.revision,
                      paused=self.paused, stopping=self.stopping, request=command.get("request"))

    def before_lease(self, slot):
        with self.condition:
            while self.paused and not self.stopping and slot < self.workers:
                self.condition.wait()
            if self.stopping or slot >= self.workers:
                return None
            if self.applied.get(slot) != self.revision:
                self.applied[slot] = self.revision
                self.emit("applied", slot=slot, revision=self.revision)
            return dict(self.config)

    def wait(self, seconds):
        with self.condition:
            if not self.stopping:
                self.condition.wait(seconds)

    def started(self, slot, job):
        with self.condition:
            self.started_jobs[slot] = time.monotonic()
        self.emit("job_started", slot=slot, client=job["client"], addr=job["addr"],
                  unit=job.get("unit"), size=job.get("size"), previous=job.get("score", 0))

    def finished(self, slot, job, score):
        with self.condition:
            now = time.monotonic()
            self.completed += 1
            receipt = job.get("receipt") or {}
            gain = bool(receipt.get("verified") and receipt.get("improved")) if "receipt" in job else score > job.get("score", 0)
            self.matched += gain and score == 100
            self.improved += gain and score != 100
            self.emit("job_finished", slot=slot, client=job["client"], addr=job["addr"], score=score,
                      unit=job.get("unit"), size=job.get("size"), previous=job.get("score", 0),
                      new_exact=gain and score == 100, improved=gain,
                      seconds=round(now - self.started_jobs.pop(slot, now), 1))
            if now - self.last_report >= 30:
                self.emit("benchmark", workers=self.workers, completed=self.completed,
                          matched=self.matched, improved=self.improved, errors=self.errors,
                          per_minute=round(self.completed * 60 / max(now - self.started_at, 1), 1))
                self.last_report = now
        with self.budget._lock:
            self.emit("usage", requests=self.budget.requests, tokens=self.budget.tokens,
                      cost=self.budget.cost if self.cost_known else None)
            exhausted = any(limit is not None and used >= limit for used, limit in (
                (self.budget.requests, self.budget.max_requests),
                (self.budget.tokens, self.budget.max_tokens), (self.budget.cost, self.budget.max_cost)))
        if exhausted:
            self.emit("log", slot=slot, message="Cloud budget cap reached; finishing session.")
            self.command({"action": "stop"})


def native_loop(config, control, emit):
    """Native integration: each pass lets the model edit native files that define waiting exact targets, submits
    locally proven edits as one verified batch; discovery continues while the server verifies."""
    from roc import integration, native_sweep, research
    outage_started = None
    def server_wait(error):
        nonlocal outage_started
        if error.category == 'auth_fail':
            emit('error', slot=0, message='Server authentication failed; saved proofs retained: ' + str(error))
            control.command({'action': 'stop'})
            return False
        if error.category in ('offline', 'server_fail'):
            if outage_started is None:
                outage_started = time.monotonic()
            if time.monotonic() - outage_started >= 7200:
                emit('error', slot=0, message='Server unreachable for two hours; saved proofs retained. Session stopped.')
                control.command({'action': 'stop'})
                return False
        emit('log', slot=0, message='Server request failed; saved proofs retained. Retry in 30s: ' + str(error))
        emit('stage', message='Waiting for server; retrying in 30s', task_status='running')
        control.wait(30)
        return not control.stopping
    if not providers.available(config["model"]):
        raise providers.ProviderError("provider_key", providers.credential_hint(config["model"]))
    spec = json.loads(json.dumps(research.recipes()["native-model-2008"]))
    emit('log', slot=0, message='Startup: validating ABI, RTTI and dependency compiler profiles')
    from roc.rebuild_install import prepare
    prepare(log=lambda message: emit('log', slot=0, message=message))
    worker.save_settings(user=config["user"], server=config["server"])
    emit("log", slot=0, message="Startup: syncing accepted native baseline (unchanged overlays are reused)")
    while not control.stopping:
        try:
            integration.command(SimpleNamespace(action="sync", server=config["server"], user=config["user"], token=None))
            outage_started = None
            break
        except worker.ApiFailure as error:
            if not server_wait(error):
                return
    emit("log", slot=0, message="Startup complete: selecting exact mined targets for parallel integration")
    def native_event(kind, **fields):
        emit(kind, **fields)
        if fields.get("error_category") in providers.FATAL_ERRORS or fields.get("error_category") == "cloud_budget":
            emit("error", slot=fields["slot"], message="Provider unavailable; session stopped. " + fields.get("error", ""))
            control.command({"action": "stop"})

    tried = set()
    file_offsets, retry_targets = {}, {}
    tried_revision = None
    target_offset = 0
    def remember(summary, step):
        nonlocal tried_revision
        revision = summary.get('base_revision')
        if revision is not None and revision != tried_revision:
            tried.clear()
            file_offsets.clear()
            retry_targets.clear()
            tried_revision = revision
        tried.update(summary.get('files_tried', []))
        retry_targets.update(summary.get('pending_files', {}))
        for rel in summary.get('files_tried', []):
            file_offsets[rel] = file_offsets.get(rel, target_offset) + step
    def report(message):
        emit('stage', message=str(message), task_status='running')
    def recover_pass(error):
        # A rejected candidate must not kill discovery or regenerate the same
        # files immediately. Native run archived their source and local proofs.
        path = native_sweep.ROOT / 'work/research/native-model-2008/summary.json'
        if path.exists():
            remember(json.loads(path.read_text()), current['native_compile_batch'])
        if isinstance(error, native_sweep.BaselineAdvanced):
            emit('stage', message='Accepted baseline advanced; rechecking saved proofs without AI', task_status='running')
            control.wait(1)
            return
        control.errors += 1
        emit('error', slot=0, message='Native pass failed; proofs retained. Continuing in 30s: ' + str(error))
        emit('stage', message='Recovering native pass; retrying in 30s', task_status='running')
        control.wait(30)
    pending = set()
    def refresh_pending():
        if not pending:
            return False
        api = worker.Api(config["server"], worker.load_settings().get("token"))
        advanced = False
        try:
            for identifier in list(pending):
                for job in api.call("/v1/integration?id=" + identifier)["jobs"]:
                    if job["state"] not in ("accepted", "rejected", "failed"):
                        continue
                    pending.remove(identifier)
                    credits = (job.get("receipt") or {}).get("credits", 0) if job["state"] == "accepted" else 0
                    control.matched += credits
                    advanced |= job["state"] == "accepted"
                    emit("native_accepted" if credits else "log", credits=credits,
                         message="Native batch %s: %s · %d new server verified" % (identifier[:8], job["state"], credits))
            emit("benchmark", workers=control.workers, completed=control.completed,
                 matched=control.matched, improved=0, errors=control.errors)
        except worker.ApiFailure:
            pass
        finally:
            api.close()
        return advanced
    while not control.stopping:
        current = control.before_lease(0)
        if current is None:
            break
        if refresh_pending():
            tried.clear()
            file_offsets.clear()
        for slot in range(control.workers):
            emit("applied", slot=slot, revision=control.revision)
        inflight = providers.cloud_slots(current["model"],control.workers,current["cloud_concurrency"])
        emit("stage", message="Integrator: %d file workers · %d AI requests · %d compilers · up to %d files per batch" % (
            control.workers, inflight, native_sweep.resolve_compile_workers(current["native_compile_workers"], control.workers), current["native_batch_files"]))
        spec["native_sweep"].update(llm=current["model"], model=current["model"],
            rounds=3 if current["rounds"] == "auto" else current["rounds"], wait=False, exclude_files=sorted(tried),
            max_files=current["native_batch_files"], context=current["native_context"],
            generation=current["native_generation"],
            compile_batch=current["native_compile_batch"],
            target_offset=target_offset, resume_saved=True, rolling_workers=True,
            file_offsets=dict(file_offsets), retry_targets=dict(retry_targets), tried_revision=tried_revision,
            compile_workers=current["native_compile_workers"],
            provider_options={"allow_cloud": current["cloud_allowed"], "budget": control.budget,
                "gate": providers.CloudGate(inflight),
                "max_tokens": 3072 if current["max_tokens"] == "auto" else current["max_tokens"],
                "thinking": current["thinking"], "reasoning_effort": current["reasoning_effort"] if current["reasoning_effort"] not in (None, "auto") else
                    ("low" if current["model"].startswith(("codex:", "claude:")) else None),
                "event": native_event,
                "before_request": lambda: control.before_lease(0) is not None})
        try:
            summary = native_sweep.run(spec, "native-model-2008", server=config["server"] or None, jobs=control.workers,
                                       log=report)
            outage_started = None
        except worker.ApiFailure as error:
            if error.category == 'bad_request':
                outage_started = None
                recover_pass(error)
            elif not server_wait(error):
                break
            continue
        except (Exception, SystemExit) as error:  # noqa: BLE001 - failed native passes preserve proofs and retry
            if getattr(error, 'category', '') in providers.FATAL_ERRORS or getattr(error, 'category', '') == 'cloud_budget':
                emit('error', slot=0, message=str(error))
                control.command({'action': 'stop'})
                break
            outage_started = None
            recover_pass(error)
            continue
        emit("log", slot=0, message="native pass: %s, %s local exact, %s verified" % (
            summary.get("state"), summary.get("local_exact", 0), summary.get("new_verified", 0)))
        remember(summary, current['native_compile_batch'])
        if summary.get("job"):
            pending.add(summary["job"])
        control.completed += len(summary.get("files_tried", []))
        control.matched += summary.get("new_verified", 0)
        emit("benchmark", workers=control.workers, completed=control.completed,
             matched=control.matched, improved=0, errors=control.errors)
        with control.budget._lock:
            emit("usage", requests=control.budget.requests, tokens=control.budget.tokens,
                 cost=control.budget.cost if control.cost_known else None)
            exhausted = any(limit is not None and used >= limit for used, limit in (
                (control.budget.requests, control.budget.max_requests),
                (control.budget.tokens, control.budget.max_tokens), (control.budget.cost, control.budget.max_cost)))
        if exhausted:
            emit("log", slot=0, message="Cloud budget cap reached; finishing session.")
            control.command({"action": "stop"})
        if not summary.get("files_tried") and not summary.get("job"):
            emit("stage", message="Discovery cycle complete; checking updates and rotating targets within 60s", task_status='running')
            signature = None
            restart_at = time.monotonic() + 60
            while not control.stopping:
                if refresh_pending():
                    tried.clear()
                    file_offsets.clear()
                    break
                api = worker.Api(current["server"], worker.load_settings().get("token"))
                try:
                    status = next((row for row in api.call("/v1/status")["clients"] if row["client"] == "2008-06"), {})
                    changed = (status.get("matched"), status.get("integrated"), status.get("functions"), control.revision)
                    if signature is not None and changed != signature:
                        tried.clear()
                        file_offsets.clear()
                        break
                    signature = changed
                except worker.ApiFailure:
                    pass  # Keep local proofs while the shared service recovers.
                finally:
                    api.close()
                if time.monotonic() >= restart_at:
                    tried.clear()
                    file_offsets.clear()
                    target_offset += current['native_compile_batch']
                    report('Starting next discovery cycle with rotated pending targets')
                    break
                control.wait(30)
    for slot in range(control.workers):
        emit("slot_stopped", slot=slot)


def command_lines(stream):
    """Read controller JSON without holding stdin's buffered lock at shutdown."""
    pending = b''
    while True:
        chunk = os.read(stream.fileno(), 65536)
        if not chunk:
            if pending:
                yield pending.decode('utf-8')
            return
        pending += chunk
        while b'\n' in pending:
            line, pending = pending.split(b'\n', 1)
            yield line.decode('utf-8')


def main(initial=None, receive_commands=True):
    commands = command_lines(sys.stdin)
    initial = initial or json.loads(next(commands))
    if not receive_commands:
        initial["terminal"] = True
    initial["config"] = validate(initial["config"])
    if initial["config"].get("lease_mode") == "native" and not os.environ.get("ROC_INTEGRATOR_PRIVATE"):
        from roc import integrator
        return integrator.run_private(initial, receive_commands, commands)
    output_lock = threading.Lock()

    def emit(event, **fields):
        with output_lock:
            if initial.get("terminal"):
                slot = "w%d" % (fields["slot"] + 1) if "slot" in fields else "roc"
                if event == "native_result":
                    print("[%s] %s +%d local exact (awaiting verification) | %.1fs%s" % (
                        slot, fields["file"], fields["local_exact"], fields["seconds"],
                        " | " + fields["error"] if fields.get("error") else ""), flush=True)
                elif event == "native_started":
                    print("[%s] %s | baseline" % (slot, fields["file"]), flush=True)
                elif event == "native_progress":
                    if "Requesting" in fields["message"] or "new exact" in fields["message"]:
                        print("[%s] %s | %s" % (slot, fields["file"], fields["message"]), flush=True)
                elif event in ("log", "error", "stage", "native_accepted"):
                    print("[%s] %s" % (slot, fields.get("message", "")), flush=True)
            else:
                print("ROC_EVENT " + json.dumps(dict(event=event, **fields)), flush=True)

    config = validate(initial["config"])
    control = Control(config, emit)
    emit("control", config=config, revision=1, paused=False, stopping=False)
    emit("log", slot=0, message="Startup: checking installed client binary, historical compiler and analysis")
    prepare_clients(config, lambda message: emit("log", slot=0, message=message))
    emit("log", slot=0, message="Startup: client dependencies ready")

    def receive():
        for line in commands:
            try:
                control.command(json.loads(line))
            except (ValueError, KeyError, TypeError) as error:
                emit("rejected", message=str(error))
        control.command({"action": "stop"})

    if receive_commands:
        threading.Thread(target=receive, daemon=True).start()
    shared_examples, shared_sources = {}, {}
    family_state, family_lock = {"id": config["family_id"]}, threading.Lock()
    gate = providers.CloudGate(providers.cloud_slots(config["model"],control.workers,config["cloud_concurrency"]))
    threads, failures = {}, []

    def run_slot(slot):
        with control.condition:
            current = dict(control.config)
        options = {key: value for key, value in current.items() if key not in
                   ("workers", "client", "max_cloud_requests", "max_cloud_tokens", "max_cloud_cost", "cloud_concurrency",
                    "native_batch_files", "native_compile_workers", "native_context", "native_generation", "native_compile_batch")}
        options.update(token=initial.get("token"), only=[current["client"]] if current["client"] else None,
                       model=current["model"] or None, forever=True, cloud_budget=control.budget, cloud_gate=gate,
                       examples_cache=shared_examples, source_cache=shared_sources,
                       family_state=family_state, family_lock=family_lock, control=control, slot=slot,
                       log=lambda message: emit("log", slot=slot, message=str(message)))
        try:
            from roc import telemetry
            telemetry.local.emit = lambda event, **fields: emit(event, slot=slot, **fields)
            worker.run(**options)
        except (Exception, SystemExit) as error:
            failures.append(error)
            with control.condition:
                control.errors += 1
            emit("error", slot=slot, message=str(error))
            control.command({"action": "stop"})
        finally:
            emit("slot_stopped", slot=slot)

    worker.keep_awake()
    if config["lease_mode"] == "native":
        native_loop(config, control, emit)
        return
    while True:
        with control.condition:
            if not control.stopping:
                for slot in range(control.workers):
                    if slot not in threads or not threads[slot].is_alive():
                        threads[slot] = threading.Thread(target=run_slot, args=(slot,), daemon=True)
                        threads[slot].start()
            if control.stopping and not any(thread.is_alive() for thread in threads.values()):
                break
            control.condition.wait(0.3)
    if failures:
        raise SystemExit(1)


if __name__ == "__main__":
    main()

roc/integration.py.base:
"""Native-source promotion: durable claims, declarative uploads and verified credit."""
import hashlib
import json
import os
import re
import socket
import sqlite3
import subprocess
import sys
import threading
import time
import uuid
from pathlib import Path, PurePosixPath

ROOT = Path(__file__).resolve().parent.parent
CLIENT = "2008-06"
MODULE = "rbxgs-app"
LEASE_SECONDS = 2 * 3600
MAX_CLAIMS = 1024
MAX_MERGE = 8  # queued jobs verified together in one linked rebuild
MAX_TARGETS = 100_000
MAX_OVERLAY_PATHS = 1024
MAX_EDITS_PER_PATH = 4096
MAX_OVERLAY_BYTES = 24 * 1024 * 1024
MAX_EVIDENCE_BYTES = 2 * 1024 * 1024
MAX_REQUEST_BYTES = 32 * 1024 * 1024
SCHEMA = """
CREATE TABLE IF NOT EXISTS integration_claims(
 id TEXT PRIMARY KEY, client TEXT, unit TEXT, user TEXT, worker TEXT,
 expires REAL, state TEXT, addresses TEXT, base TEXT, UNIQUE(client,unit));
CREATE TABLE IF NOT EXISTS integration_jobs(
 id TEXT PRIMARY KEY, claim_id TEXT, digest TEXT UNIQUE, user TEXT, model TEXT,
 unit TEXT, base TEXT, patches TEXT, evidence TEXT, state TEXT, phase TEXT,
 created REAL, updated REAL, receipt TEXT);
CREATE TABLE IF NOT EXISTS integration_credit(
 client TEXT, addr TEXT, user TEXT, model TEXT, job TEXT, ts REAL,
 PRIMARY KEY(client,addr));
CREATE TABLE IF NOT EXISTS integration_accepted(
 job TEXT PRIMARY KEY, patches TEXT, ts REAL);
CREATE TABLE IF NOT EXISTS integration_bases(
 revision TEXT PRIMARY KEY, payload TEXT);
CREATE TABLE IF NOT EXISTS integration_config(
 key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS integration_queue_priority(
 job TEXT PRIMARY KEY, requested INTEGER);
"""


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def atomic_json(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + "." + uuid.uuid4().hex + ".tmp")
    temp.write_text(json.dumps(value, indent=1) + "\n", encoding="utf-8")
    temp.replace(path)


def native_token(root=ROOT, fallback=None, create=False):
    """Read legacy native credentials for older servers; public servers need none."""
    import secrets
    secret = os.environ.get("ROC_NATIVE_TOKEN") or fallback
    path = Path(root) / "local/config/native-integration-token"
    if secret:
        return secret
    if path.exists():
        return path.read_text(encoding="utf-8").strip()
    if create:
        path.parent.mkdir(parents=True, exist_ok=True)
        secret = secrets.token_urlsafe(32)
        with path.open("x", encoding="utf-8") as stream:
            stream.write(secret + "\n")
        path.chmod(0o600)
        return secret
    return None


def validate_patches(patches):
    if not isinstance(patches, dict) or not 1 <= len(patches) <= MAX_OVERLAY_PATHS:
        raise ValueError("Need 1-%d source overlay paths" % MAX_OVERLAY_PATHS)
    if len(json.dumps(patches).encode()) > MAX_OVERLAY_BYTES:
        raise ValueError("Overlay exceeds %d bytes" % MAX_OVERLAY_BYTES)
    for name, change in patches.items():
        if not isinstance(name, str):
            raise ValueError("Overlay paths must be strings")
        path = PurePosixPath(name)
        if ("\\" in name or ":" in name or path.is_absolute() or ".." in path.parts
                or path.as_posix() != name or len(path.parts) < 2
                or path.parts[0] not in ("App", "Network", "RbxView", "RbxGraphics", "Rendering")
                or path.suffix not in (".h", ".hpp", ".cpp", ".inl", ".c")):
            raise ValueError("Not a permitted native source path: " + name)
        before = []
        if isinstance(change, dict):
            if set(change) != {"before", "after"} or not isinstance(change["before"], list):
                raise ValueError("A recipe replacement needs before/after lists")
            before, edits = change["before"], change["after"]
        else:
            edits = change
        if not isinstance(edits, list) or not 1 <= len(edits) <= MAX_EDITS_PER_PATH or len(before) > MAX_EDITS_PER_PATH:
            raise ValueError("Need 1-%d edits per path" % MAX_EDITS_PER_PATH)
        for edit in edits:
            if (not isinstance(edit, list) or len(edit) != 2
                    or not all(isinstance(s, str) for s in edit)):
                raise ValueError("An edit must be [old_text,new_text]")
            old, new = edit
            if edit in before:
                continue
            if old.startswith("@") and not old.startswith("@all:"):
                raise ValueError("Uploaded whole-file adoption/directives are not allowed")
            if old == new or not new and not old:
                raise ValueError("Empty or unchanged edit")
            if re.search(r"\b(?:__asm|__emit)\b|\basm\s*\(", new):
                raise ValueError("Assembly/byte emission is not a source promotion")
            if re.search(r"\breinterpret_cast\b|\b(?:char|BYTE)\s+pad\w*\s*\[", new):
                raise ValueError("Padding structs and offset views are not native source")
            types = r"\b(?:struct|class|union)\s+([\w:]+)\s*(?::[^;{]+)?\{"
            if set(re.findall(types, new)) - set(re.findall(types, old)):
                raise ValueError("Promote existing native classes; do not append invented snippet types")
    return patches


def merge_patches(base, additions):
    result = {name: list(edits) for name, edits in base.items()}
    for name, change in additions.items():
        if isinstance(change, dict):
            if result.get(name, []) != change["before"]:
                raise ValueError("Stale recipe replacement: " + name)
            result[name] = list(change["after"])
        else:
            result.setdefault(name, []).extend(change)
    return result


def overlay_delta(base, candidate):
    """Add recipes, or replace an existing recipe with an exact baseline guard."""
    result = {}
    for name in set(base) | set(candidate):
        before, after = base.get(name, []), candidate.get(name, [])
        if not after and before:
            raise ValueError("Cannot remove a complete accepted source overlay: " + name)
        if after[:len(before)] != before:
            result[name] = {"before": before, "after": after}
        elif len(after) > len(before):
            result[name] = after[len(before):]
    return validate_patches(result)


class Promotions:
    def __init__(self, store, root=ROOT):
        self.store, self.root = store, Path(root)
        self.directory = self.root / "work" / "integration"
        self.overlay = self.root / "rebuild" / CLIENT / "patches" / "rbxgs-client.json"
        self.generator = self.overlay.with_name("make_rbxgs_client.py")
        self.wake = threading.Event()
        self.worker_error = None
        self.catalog_key, self.catalog_rows = None, []
        self.native_paths = {}
        with store.lock:
            store.db.executescript(SCHEMA)
            initial = self.overlay.with_name("native-promotions.json")
            store.db.execute("INSERT OR IGNORE INTO integration_config VALUES('initial_patches',?)",
                             (initial.read_text(encoding="utf-8") if initial.exists() else "{}",))
            store.db.commit()

    def accepted(self):
        with self.store.lock:
            rows = self.store.db.execute("SELECT patches FROM integration_accepted ORDER BY ts,job").fetchall()
            initial = json.loads(self.store.db.execute(
                "SELECT value FROM integration_config WHERE key='initial_patches'").fetchone()[0])
        result = initial if isinstance(initial, list) else [initial] if initial else []
        for row in rows:
            result.append(json.loads(row[0]))
        return result

    def baseline(self):
        if not self.generator.exists() or not self.overlay.exists():
            raise ValueError("Native rebuild inputs are not installed on this server")
        with self.store.lock, self.store.db:
            base = json.loads(self.overlay.read_text(encoding="utf-8"))
            generator = hashlib.sha256(self.generator.read_bytes()).hexdigest()
            initial = json.loads(self.store.db.execute(
                "SELECT value FROM integration_config WHERE key='initial_patches'").fetchone()[0])
            accepted = initial if isinstance(initial, list) else [initial] if initial else []
            for row in self.store.db.execute("SELECT patches FROM integration_accepted ORDER BY ts,job"):
                accepted.append(json.loads(row[0]))
            result = {"revision": digest([base, generator]), "overlay": base,
                      "generator": generator, "accepted": accepted,
                      "limits": {"claims": MAX_CLAIMS, "targets": MAX_TARGETS,
                                 "overlay_paths": MAX_OVERLAY_PATHS, "edits_per_path": MAX_EDITS_PER_PATH,
                                 "overlay_bytes": MAX_OVERLAY_BYTES, "evidence_bytes": MAX_EVIDENCE_BYTES,
                                 "request_bytes": MAX_REQUEST_BYTES}}
            self.store.db.execute("INSERT OR IGNORE INTO integration_bases VALUES(?,?)",
                                  (result["revision"], json.dumps(result)))
        return result

    def catalog(self, requested_unit=None):
        path = self.root / "rebuild" / CLIENT / "manifests" / "functions.json"
        report = path.parent.parent / "out" / "RbxgsApp" / "report.json"
        queue = path.parent.parent / "out" / "agent-queue.json"
        with self.store.lock:
            accepted_version = self.store.db.execute("SELECT COUNT(*),MAX(ts) FROM integration_accepted").fetchone()
        key = (path.stat().st_mtime_ns, report.stat().st_mtime_ns if report.exists() else 0,
               queue.stat().st_mtime_ns if queue.exists() else 0, accepted_version, requested_unit)
        if self.catalog_key != key:
            from collections import defaultdict
            tree = self.root / "tools/rbxgs/Client"
            header_texts = [(p, p.read_text(errors="replace")) for p in (tree / "App/include").rglob("*.h")]
            headers = "\n".join(t for _, t in header_texts)
            self.native_paths = {}
            for p, text in header_texts:
                for cls in re.findall(r"\bclass\s+(\w+)", text):
                    self.native_paths.setdefault(cls, set()).add(p.relative_to(tree).as_posix())
            for p in (tree / "App").rglob("*.cpp"):
                if p.name.startswith("roc_"):
                    continue
                for cls in set(re.findall(r"\b(\w+)::~?\w+\s*\(", p.read_text(errors="replace"))):
                    self.native_paths.setdefault(cls, set()).add(p.relative_to(tree).as_posix())
            owned = set(json.loads(report.read_text()).get("owned_addrs", [])) if report.exists() else set()
            with self.store.lock:
                accepted = self.store.db.execute("SELECT receipt FROM integration_jobs WHERE state='accepted'").fetchall()
            for receipt, in accepted:
                owned.update(json.loads(receipt).get("gains", []))
            groups = defaultdict(list)
            state = json.loads(queue.read_text()) if queue.exists() else {}
            skipped = (set(state.get("done", [])) - {requested_unit}) | set(state.get("parked", {}))
            for f in json.loads(path.read_text(encoding="utf-8")):
                unit = f.get("unit") or ""
                m = re.fullmatch(r"RBX::(?:\w+::)*(\w+)", unit)
                if (f.get("score") == 100 and f.get("source_kind") == "snippet"
                        and unit not in skipped and f["addr"] not in owned and f["size"] >= 24 and m
                        and re.search(r"\bclass\s+" + re.escape(m[1]) + r"\b", headers)):
                    groups[unit].append(f)
            self.catalog_rows = sorted(groups.items(), key=lambda x: (-len(x[1]), x[0]))
            self.catalog_key = key
        return self.catalog_rows

    def native_names(self):
        """rebuild/2008-06/out/native-names.json ({addr: {symbol, score, strings}}), reloaded when it changes."""
        path = self.root / "rebuild" / CLIENT / "out" / "native-names.json"
        stamp = path.stat().st_mtime if path.exists() else None
        if getattr(self, "_names_stamp", False) != stamp:
            self._names = json.loads(path.read_text()) if stamp else {}
            self._names_stamp = stamp
        return self._names

    def evidence(self):
        """Native discovery inputs for contributor PCs without local rebuild artifacts: rebuilt symbol names, the
        addresses the accepted linked rebuild owns, and every exact mined RBX target ({addr: [unit, size]})."""
        progress = self.directory / "progress-native.json"
        with self.store.lock:
            rows = self.store.db.execute("SELECT addr,unit,size FROM funcs WHERE client=? AND score=100 AND unit LIKE 'RBX::%'",
                                         (CLIENT,)).fetchall()
        return {"names": self.native_names(),
                "linked": json.loads(progress.read_text())["addresses"] if progress.exists() else [],
                "targets": {addr: [unit, size] for addr, unit, size in rows}}

    def packet(self, claim, baselines=None, abi=None, compact=False):
        identifier, unit, user, worker, expires, addresses, revision = claim
        evidence = []
        for addr in json.loads(addresses)[:5]:
            path = self.root / "src" / CLIENT / (addr + ".cpp")
            evidence.append({"addr": addr, "source": path.read_text(errors="replace")[:10000]
                             if path.exists() else "Use roc pull to obtain this exact source."})
            if (self.root / "clients/2008-06/Roblox.exe").exists():
                from roc import match
                code, _, _ = match.target(CLIENT, addr)
                instructions = match.disasm(code, int(addr, 16))
                evidence[-1]["disassembly"] = instructions[:200]
                evidence[-1]["disassembly_truncated"] = len(instructions) > 200
        baselines = baselines if baselines is not None else {}
        if revision not in baselines:
            with self.store.lock:
                baselines[revision] = json.loads(self.store.db.execute("SELECT payload FROM integration_bases WHERE revision=?",
                                                                      (revision,)).fetchone()[0])
        if abi is None:
            path = self.root / "rebuild" / CLIENT / "manifests" / "abi-evidence.json"
            abi = json.loads(path.read_text()) if path.exists() else {}
        names = self.native_names()
        packet = {"id": identifier, "client": CLIENT, "module": MODULE, "unit": unit,
                "user": user, "worker": worker, "expires": expires,
                "addresses": json.loads(addresses), "base_revision": revision,
                "snippets": evidence,
                # Real rebuilt symbol per target where vtables/call graph name it, with its current rebuilt score.
                "native_names": {a: names[a] for a in json.loads(addresses) if a in names},
                "native_paths": sorted(self.native_paths.get(unit.rsplit("::", 1)[-1], [])),
                "abi": abi.get(unit, {}),
                "instructions": "Edit make_rbxgs_client.py only; regenerate; submit a declarative overlay. "
                "Derive every change from target bytes. No pad structs, offset views or invented fields."}
        if not compact:
            packet["baseline"] = baselines[revision]
        return packet

    def claim(self, user, worker, count=1, unit=None, targets=None, compact=False):
        if type(count) is not int or not 1 <= count <= MAX_CLAIMS:
            raise ValueError("Claim count must be 1-%d" % MAX_CLAIMS)
        if targets is not None and (type(targets) is not int or not 1 <= targets <= MAX_TARGETS):
            raise ValueError("Target count must be 1-%d" % MAX_TARGETS)
        if targets is not None:
            count = MAX_CLAIMS
        if not re.fullmatch(r"[A-Za-z0-9_.-]{2,32}", user) or not worker or len(worker) > 100:
            raise ValueError("Need a valid user and worker identity")
        revision = self.baseline()["revision"]
        candidates = self.catalog(unit) if unit else self.catalog()
        now, claimed, target_count = time.time(), [], 0
        with self.store.lock, self.store.db:
            # IMMEDIATE also serializes two separate server connections/processes.
            self.store.db.execute("BEGIN IMMEDIATE")
            for name, functions in candidates:
                if unit and name != unit:
                    continue
                old = self.store.db.execute("SELECT id,user,worker,expires,state FROM integration_claims "
                                            "WHERE client=? AND unit=?", (CLIENT, name)).fetchone()
                if old and (old[4] == "submitted" or old[3] > now):
                    if old[1:3] != (user, worker) or old[4] != "claimed":
                        continue
                    row = self.store.db.execute("SELECT id,unit,user,worker,expires,addresses,base "
                                                "FROM integration_claims WHERE id=?", (old[0],)).fetchone()
                else:
                    row = (uuid.uuid4().hex, name, user, worker, now + LEASE_SECONDS,
                           json.dumps([f["addr"] for f in functions]), revision)
                    self.store.db.execute("DELETE FROM integration_claims WHERE client=? AND unit=?", (CLIENT, name))
                    self.store.db.execute("INSERT INTO integration_claims "
                                          "(id,client,unit,user,worker,expires,state,addresses,base) "
                                          "VALUES(?,?,?,?,?,?,'claimed',?,?)",
                                          (row[0], CLIENT, name, user, worker, row[4], row[5], revision))
                if targets is not None and row[6] != revision:
                    continue  # A target-sized batch must share one submit baseline.
                claimed.append(row)
                target_count += len(json.loads(row[5]))
                if len(claimed) == count or targets is not None and target_count >= targets:
                    break
        baselines = {}
        abi_path = self.root / "rebuild" / CLIENT / "manifests" / "abi-evidence.json"
        abi = json.loads(abi_path.read_text()) if abi_path.exists() else {}
        result = {"claims": [self.packet(row, baselines, abi, compact) for row in claimed],
                  "classes": len(claimed), "targets": target_count}
        if compact:
            result["baselines"] = baselines
        return result

    def renew(self, user, identifier, release=False, reason=None):
        return self.renew_many(user, [identifier], release, reason)

    def renew_many(self, user, identifiers, release=False, reason=None):
        if (not isinstance(identifiers, list) or not 1 <= len(identifiers) <= MAX_CLAIMS
                or any(not isinstance(i, str) for i in identifiers) or len(set(identifiers)) != len(identifiers)):
            raise ValueError("Need 1-%d distinct claim IDs" % MAX_CLAIMS)
        parked = release and bool(reason)
        if reason is not None and (not isinstance(reason, str) or len(reason) > 500):
            raise ValueError("Park reason must be at most 500 characters")
        with self.store.lock, self.store.db:
            now = time.time()
            expires = now if release and not parked else now + LEASE_SECONDS
            state = "parked: " + reason if parked else "released" if release else "claimed"
            changed = self.store.db.executemany("UPDATE integration_claims SET expires=?,state=? "
                "WHERE id=? AND user=? AND state='claimed' AND expires>?",
                [(expires, state, identifier, user, now) for identifier in identifiers]).rowcount
        return {"ok": changed == len(identifiers), "changed": changed, "requested": len(identifiers)}

    def submit(self, user, body):
        patches = validate_patches(body.get("patches"))
        model, evidence = body.get("model"), body.get("evidence")
        if not isinstance(model, str) or not model.strip() or len(model) > 120:
            raise ValueError("Record the actual model, or human for manual work")
        if not isinstance(evidence, str) or not 1 <= len(evidence.encode()) <= MAX_EVIDENCE_BYTES:
            raise ValueError("Evidence notes are required")
        cited = set(re.findall(r"(?i)(?<![0-9a-f])[0-9a-f]{8}(?![0-9a-f])", evidence.lower()))
        identifiers = body.get("claims", [body.get("claim")])
        if (not isinstance(identifiers, list) or not 1 <= len(identifiers) <= MAX_CLAIMS
                or any(not isinstance(i, str) for i in identifiers) or len(set(identifiers)) != len(identifiers)):
            raise ValueError("Need 1-%d distinct claim IDs" % MAX_CLAIMS)
        identifiers = sorted(identifiers)
        base = str(body.get("base_revision", ""))
        retry = body.get("retry_of")
        if retry is not None and (not isinstance(retry, str) or not re.fullmatch(r"[0-9a-f]{32}", retry)):
            raise ValueError("Invalid retry job ID")
        key = digest([user, identifiers, base, model, patches, evidence, retry])
        with self.store.lock, self.store.db:
            self.store.db.execute("BEGIN IMMEDIATE")
            previous = self.store.db.execute("SELECT id,state FROM integration_jobs WHERE digest=?", (key,)).fetchone()
            if previous:
                return {"id": previous[0], "state": previous[1], "duplicate": True}
            if retry and not self.store.db.execute("SELECT 1 FROM integration_jobs WHERE id=? AND user=? "
                    "AND state='rejected' AND claim_id=?", (retry, user, json.dumps(identifiers))).fetchone():
                raise ValueError("Only your rejected batch can be retried")
            claims = []
            for identifier in identifiers:
                claim = self.store.db.execute("SELECT unit,addresses,base FROM integration_claims "
                    "WHERE id=? AND user=? AND state='claimed' AND expires>?", (identifier, user, time.time())).fetchone()
                if not claim or claim[2] != base:
                    raise ValueError("Missing, expired or mismatched claim; renew/reclaim before submitting")
                if not cited.intersection(json.loads(claim[1])):
                    raise ValueError("Cite a claimed target address for " + claim[0])
                claims.append(claim)
            job = uuid.uuid4().hex
            self.store.db.execute("INSERT INTO integration_jobs VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (job, json.dumps(identifiers), key, user, model, ", ".join(c[0] for c in claims), base, json.dumps(patches), evidence,
                 "queued", "queued", time.time(), time.time(), None))
            for identifier in identifiers:
                self.store.db.execute("UPDATE integration_claims SET state='submitted' WHERE id=?", (identifier,))
        self.wake.set()
        return {"id": job, "state": "queued", "duplicate": False}

    def status(self, identifier=None):
        with self.store.lock:
            rows = self.store.db.execute("SELECT id,user,model,unit,state,phase,created,updated,receipt "
                "FROM integration_jobs " + ("WHERE id=? " if identifier else "") + "ORDER BY created DESC LIMIT 100",
                (identifier,) if identifier else ()).fetchall()
            leaders = self.store.db.execute("SELECT user,model,COUNT(*) FROM integration_credit "
                                           "GROUP BY user,model ORDER BY COUNT(*) DESC,user").fetchall()
            parked = self.store.db.execute("SELECT unit,state,expires FROM integration_claims "
                                           "WHERE state LIKE 'parked:%' AND expires>?", (time.time(),)).fetchall()
        return {"verifier_error": self.worker_error,
                "parked": [{"unit": u, "reason": s[8:], "until": e} for u, s, e in parked],
                "jobs": [dict(zip(("id", "user", "model", "unit", "state", "phase", "created", "updated", "receipt"),
                                 (*r[:-1], json.loads(r[-1]) if r[-1] else None))) for r in rows],
                "leaderboard": [{"user": u, "model": m, "native_credits": n} for u, m, n in leaders]}

    def force_queue(self, user, identifier):
        """Prioritize an owned queued batch; the active verifier keeps running."""
        if not isinstance(identifier, str) or not re.fullmatch(r"[0-9a-f]{32}", identifier):
            raise ValueError("Invalid batch ID")
        with self.store.lock, self.store.db:
            self.store.db.execute("BEGIN IMMEDIATE")
            row = self.store.db.execute("SELECT user,state FROM integration_jobs WHERE id=?", (identifier,)).fetchone()
            if not row or row[0] != user:
                raise ValueError("Batch not found or belongs to another user")
            if row[1] != "queued":
                raise ValueError("Force queue requires a queued batch; current state: " + row[1])
            self.store.db.execute("INSERT OR REPLACE INTO integration_queue_priority VALUES(?,?)",
                                  (identifier, time.time_ns()))
            self.store.db.execute("UPDATE integration_jobs SET phase=CASE WHEN phase='solo' THEN phase "
                                  "ELSE 'priority queued' END,updated=? WHERE id=?", (time.time(), identifier))
        self.wake.set()
        return {"id": identifier, "state": "queued", "priority": "next", "waits_for_active": True}

    def take(self):
        """Prioritized jobs first, then FIFO. Later jobs from the same user/model/baseline that edit disjoint files ride along
        in one verification (one linked rebuild for all); a merged batch that fails is re-queued as solo jobs."""
        fields = ("id", "user", "model", "unit", "base", "patches", "evidence", "phase")
        with self.store.lock, self.store.db:
            self.store.db.execute("BEGIN IMMEDIATE")
            rows = [dict(zip(fields, r)) for r in self.store.db.execute(
                "SELECT j.id,j.user,j.model,j.unit,j.base,j.patches,j.evidence,j.phase FROM integration_jobs j "
                "LEFT JOIN integration_queue_priority p ON p.job=j.id "
                "WHERE j.state='queued' ORDER BY p.requested IS NULL,p.requested DESC,j.created")]
            if not rows:
                return None
            lead, members = rows[0], [rows[0]]
            if lead["phase"] != "solo":
                files = set(json.loads(lead["patches"]))
                for row in rows[1:]:
                    patches = set(json.loads(row["patches"]))
                    if len(members) < MAX_MERGE and row["phase"] != "solo" and not files & patches and \
                            (row["user"], row["model"], row["base"]) == (lead["user"], lead["model"], lead["base"]):
                        members.append(row)
                        files |= patches
            for row in members:
                self.store.db.execute("DELETE FROM integration_queue_priority WHERE job=?", (row["id"],))
                self.store.db.execute("UPDATE integration_jobs SET state='verifying',phase=?,updated=? WHERE id=?",
                                      ("snapshot" if row is lead else "merged into " + lead["id"][:8], time.time(), row["id"]))
        job = {k: lead[k] for k in fields[:-1]}
        if len(members) > 1:
            merged = {}
            for row in members:
                merged.update(json.loads(row["patches"]))
            job.update(patches=json.dumps(merged), members=[row["id"] for row in members],
                       unit=", ".join(row["unit"] for row in members),
                       evidence="\n\n".join(row["evidence"] for row in members))
        return job

    def progress(self, identifier, phase):
        with self.store.lock, self.store.db:
            self.store.db.execute("UPDATE integration_jobs SET phase=?,updated=? WHERE id=? AND state='verifying'",
                                  (phase, time.time(), identifier))

    def finish(self, job, receipt, publish=None):
        """Called only by the server's verifier; no client result/credit endpoint."""
        with self.store.lock, self.store.db:
            self.store.db.execute("BEGIN IMMEDIATE")
            current = self.store.db.execute("SELECT state FROM integration_jobs WHERE id=?", (job["id"],)).fetchone()
            if not current or current[0] != "verifying":
                return False
            accepted = receipt.get("accepted") is True
            members = job.get("members", [job["id"]])
            if len(members) > 1 and not accepted:
                # One member may have broken the shared build: verify each on its own instead of rejecting all.
                note = json.dumps({"merged_failure": receipt.get("reason", ""), "merged_jobs": members})
                for identifier in members:
                    self.store.db.execute("UPDATE integration_jobs SET state='queued',phase='solo',receipt=?,updated=? "
                                          "WHERE id=? AND state='verifying'", (note, time.time(), identifier))
                return False
            if accepted:
                for addr in receipt["new_distinct"]:
                    self.store.db.execute("INSERT OR IGNORE INTO integration_credit VALUES(?,?,?,?,?,?)",
                                         (CLIENT, addr, job["user"], job["model"], job["id"], time.time()))
                self.store.db.execute("INSERT INTO integration_accepted VALUES(?,?,?)",
                                      (job["id"], job["patches"], time.time()))
                if publish:
                    initial = json.loads(self.store.db.execute(
                        "SELECT value FROM integration_config WHERE key='initial_patches'").fetchone()[0])
                    accepted_patches = initial if isinstance(initial, list) else [initial] if initial else []
                    for row in self.store.db.execute("SELECT patches FROM integration_accepted ORDER BY ts,job"):
                        accepted_patches.append(json.loads(row[0]))
                    publish(accepted_patches)
                receipt["credits"] = self.store.db.execute("SELECT COUNT(*) FROM integration_credit WHERE job=?",
                                                           (job["id"],)).fetchone()[0]
            receipt.update({"job": job["id"], "user": job["user"], "model": job["model"], "unit": job["unit"]})
            if len(members) > 1:
                receipt["merged_jobs"] = members
            for member in members:
                self.store.db.execute("UPDATE integration_jobs SET state=?,phase=?,receipt=?,updated=? WHERE id=?",
                    ("accepted" if accepted else "rejected", "complete", json.dumps(receipt), time.time(), member))
                claims = self.store.db.execute("SELECT claim_id FROM integration_jobs WHERE id=?", (member,)).fetchone()[0]
                for identifier in json.loads(claims):
                    self.store.db.execute("UPDATE integration_claims SET state=?,expires=? WHERE id=?",
                        ("released" if accepted else "claimed", 0 if accepted else time.time() + LEASE_SECONDS, identifier))
        self.catalog_key = None
        return True


def add_standins(claim):
    """Each exact snippet's binary-proven placeholder -> real symbol map (roc/standins.py), when it compiles here."""
    from roc import standins
    for item in claim.get("snippets", []):
        try:
            item["standins"] = standins.mapping(CLIENT, item["addr"], item["source"])
        except Exception as error:  # noqa: BLE001 - evidence is optional; the packet stays usable without it
            item["standins_error"] = str(error)[:200]
    return claim


def run_generator(generator, root, timeout=120):
    """Regenerate overlays with visible liveness and a bounded startup wait."""
    started = time.monotonic()
    print("Generating native overlay...", flush=True)
    process = subprocess.Popen([sys.executable, "-u", str(generator)], cwd=root,
                               stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                               creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
    while True:
        try:
            output, _ = process.communicate(timeout=10)
            break
        except subprocess.TimeoutExpired:
            elapsed = time.monotonic() - started
            print("Native overlay generator still running (%ds)" % elapsed, flush=True)
            if elapsed >= timeout:
                process.kill()
                process.communicate()
                raise TimeoutError("Native overlay generator exceeded %ds; stopped private generator" % timeout)
    if process.returncode:
        raise RuntimeError("Native overlay generation failed: " + output.decode(errors="replace")[-1500:])
    print("Native overlay ready (%.1fs)" % (time.monotonic() - started), flush=True)


def sync_client_baseline(root, base, only_if_clean=False):
    generator = root / "rebuild/2008-06/patches/make_rbxgs_client.py"
    overlay = generator.with_name("rbxgs-client.json")
    marker = root / "work/integration-client/baseline.json"
    if only_if_clean:
        if not marker.exists():
            return False
        previous = json.loads(marker.read_text())
        current = hashlib.sha256(generator.read_bytes()).hexdigest()
        if current != previous["generator"] or current != base["generator"] or \
                json.loads(overlay.read_text()) != previous["overlay"]:
            return False
    atomic_json(generator.with_name("native-promotions.json"), base["accepted"])
    if (hashlib.sha256(generator.read_bytes()).hexdigest() == base["generator"] and overlay.exists()
            and json.loads(overlay.read_text()) == base["overlay"]):
        atomic_json(marker, base)
        print("Accepted native overlay unchanged; regeneration skipped", flush=True)
        return True
    run_generator(generator, root)
    if json.loads(overlay.read_text()) != base["overlay"]:
        raise ValueError("Local source/overlay baseline differs from server; update before claiming")
    atomic_json(marker, base)
    return True


def command(args):
    from roc import worker
    if args.action == "fingerprint":
        from roc.integration_verify import input_hashes
        started = time.monotonic()
        full, live = input_hashes(ROOT)
        print(json.dumps({"inputs": full, "live": live, "seconds": round(time.monotonic() - started, 3)}))
        return
    settings = worker.load_settings()
    server = args.server or settings.get("server") or worker.site_server()
    user = args.user or settings.get("user")
    if not server or not user:
        raise SystemExit("Run roc config --server URL --user NAME first")
    api = worker.Api(server, args.token or settings.get("native_token") or native_token() or settings.get("token"))
    directory = ROOT / "work" / "integration-client"
    generator = ROOT / "rebuild/2008-06/patches/make_rbxgs_client.py"
    overlay = generator.with_name("rbxgs-client.json")
    action = args.action

    if action == "invite":
        print("Native integration is public. No invitation or native token required.")
        return

    if action == "force-queue":
        if not args.id:
            raise SystemExit("Force queue needs --id JOB_ID")
        try:
            result = api.call("/v1/integration/force-queue", {"user": user, "id": args.id})
        except worker.ApiFailure as error:
            if error.category == "bad_request" and "Unknown integration action" in str(error):
                raise SystemExit("Server needs the force-queue update and restart; active verification is unchanged") from None
            raise
        finally:
            api.close()
        print("Priority queued %s; starts after active verification completes" % result["id"])
        return

    if action == "next":
        base = api.call("/v1/integration/base")
        limits = base.get("limits", {"claims": 16})
        if args.count > limits["claims"] or getattr(args, "targets", None) is not None and not limits.get("targets"):
            raise SystemExit("Server needs the bulk integration update and restart before this request")
        if not generator.exists() or not (ROOT / "tools/rbxgs/Client/App/include").exists():
            raise SystemExit("Native integration needs the rebuild recipes and your local rbxgs source tree; see docs/INTEGRATION.md")
        if hashlib.sha256(generator.read_bytes()).hexdigest() != base["generator"]:
            raise SystemExit("Generator differs from server; preserve local edits, sync/update before claiming")
        atomic_json(generator.with_name("native-promotions.json"), base["accepted"])
        subprocess.run([sys.executable, str(generator)], cwd=ROOT, check=True)
        if json.loads(overlay.read_text()) != base["overlay"]:
            raise SystemExit("Local overlay does not match the server baseline")
        identity_file = directory / "identity.json"
        if not identity_file.exists():
            atomic_json(identity_file, {"id": uuid.uuid4().hex})
        identity = json.loads(identity_file.read_text())["id"]
        bulk = args.count > 16 or getattr(args, "targets", None) is not None
        result = api.call("/v1/integration/claim", {"user": user,
            "worker": user + "@" + socket.gethostname()[:40] + ":" + identity[:12],
            "count": args.count, "unit": args.unit, "targets": getattr(args, "targets", None),
            "compact": bulk}, **({"timeout": 300} if bulk else {}))
        for claim in result["claims"]:
            if "baseline" not in claim:
                claim["baseline"] = result["baselines"][claim["base_revision"]]
            folder = directory / "claims" / claim["id"]
            if not (folder / "packet.json").exists():
                if not bulk:
                    add_standins(claim)
                atomic_json(folder / "packet.json", claim)
                if generator.exists():
                    (folder / "generator-base.py").write_bytes(generator.read_bytes())
                prompt = ("Integrate " + claim["unit"] + " in RoConstruct (2008-06).\n\n"
                    "Read CLAUDE.md, rebuild/2008-06/POLICY.md and patches/make_rbxgs_client.py.\n"
                    "Read packet.json: exact snippets are evidence, not structures to paste.\n"
                    "Each snippet's standins maps its placeholder externs to the real symbol/RTTI type/import the exe\n"
                    "relocates at that spot (binary-proven); use the real names, never the placeholders.\n"
                    "Find the real class/method; derive fields, signatures, constants and control flow from bytes.\n"
                    "Change real C++ only through make_rbxgs_client.py overlay patches. Cite addresses.\n"
                    "Never edit tools/, src/, clients/ or bounds.json. No padding structs or offset views.\n"
                    "If a whole-file redesign is needed, record the blocker and release the claim.\n"
                    "Record address-specific evidence in notes.md. Then submit with:\n"
                    "  roc integrate submit --claim " + claim["id"] + " --model ACTUAL_MODEL --evidence-file notes.md\n"
                    "The server independently rebuilds, checks M2/M4a/M5, size/base, ownership and distinct counts.\n"
                    "Only verified new distinct native bodies receive separate native credit; raw mining points stay unchanged.\n")
                (folder / "PROMPT.md").write_text(prompt, encoding="utf-8")
                (folder / "notes.md").write_text("Evidence addresses: " + " ".join(claim["addresses"][:5]) +
                                                "\n\nDescribe the byte-proven source correction here.\n", encoding="utf-8")
            if len(result["claims"]) <= 16:
                print("%s: %d targets; claim %s\n  %s" % (claim["unit"], len(claim["addresses"]), claim["id"], folder))
        if result["claims"]:
            batch = directory / "batches" / (uuid.uuid4().hex + ".json")
            total = sum(len(c["addresses"]) for c in result["claims"])
            atomic_json(batch, {"claims": [c["id"] for c in result["claims"]], "targets": total})
            print("Claimed %d classes / %d targets; batch %s" % (len(result["claims"]), total, batch))
            if getattr(args, "targets", None) and total < args.targets:
                print("Requested %d targets; fewer eligible unclaimed targets available." % args.targets)
        if not result["claims"]:
            print("No unclaimed eligible native classes available.")
        return

    if action in ("submit", "renew", "release"):
        paths = sorted((directory / "claims").glob("*/packet.json"))
        claims = [json.loads(p.read_text(encoding="utf-8")) for p in paths]
        states = {j["id"]: j["state"] for j in api.call("/v1/integration")["jobs"]}
        def active(c):
            marker = directory / "claims" / c["id"] / "job.json"
            return not marker.exists() or states.get(json.loads(marker.read_text())["id"]) == "rejected"
        claims = [c for c in claims if c["user"] == user and
                  (c["id"] == args.claim if args.claim else active(c))]
        batch_file = getattr(args, "batch", None)
        if batch_file:
            if args.claim:
                raise SystemExit("Select --claim or --batch, not both")
            selected = set(json.loads(Path(batch_file).read_text(encoding="utf-8"))["claims"])
            claims = [c for c in claims if c["id"] in selected]
            if {c["id"] for c in claims} != selected:
                raise SystemExit("Batch contains missing or inactive local claims")
        if not claims or (len(claims) > 1 and not args.all and not batch_file):
            raise SystemExit("Select --claim ID, --batch FILE, or --all for local claims")
        if action != "submit":
            if len(claims) > 1 and api.call("/v1/integration/base").get("limits"):
                print(api.call("/v1/integration/" + action,
                    {"user": user, "claims": [c["id"] for c in claims], "reason": args.reason}))
            else:
                for c in claims:
                    print(c["id"], api.call("/v1/integration/" + action,
                        {"user": user, "claim": c["id"], "reason": args.reason}))
            return
        if not args.model or not args.evidence_file:
            raise SystemExit("Submit needs --model ACTUAL_MODEL (or human) and --evidence-file FILE")
        if len({c["base_revision"] for c in claims}) != 1:
            raise SystemExit("Batch claims have different bases; submit each baseline separately")
        subprocess.run([sys.executable, str(generator)], cwd=ROOT, check=True)
        patches = overlay_delta(claims[0]["baseline"]["overlay"], json.loads(overlay.read_text(encoding="utf-8")))
        body = {"user": user, "claims": [c["id"] for c in claims], "model": args.model,
                "base_revision": claims[0]["base_revision"], "patches": patches,
                "evidence": Path(args.evidence_file).read_text(encoding="utf-8")}
        if args.retry:
            if any(not (directory / "claims" / c["id"] / "job.json").exists() for c in claims):
                raise SystemExit("--retry needs an existing rejected batch")
            jobs = {json.loads((directory / "claims" / c["id"] / "job.json").read_text())["id"] for c in claims}
            if len(jobs) != 1:
                raise SystemExit("Retry one rejected batch at a time")
            body["retry_of"] = jobs.pop()
        result = api.call("/v1/integration/submit", body)
        folder = directory / "jobs" / result["id"]
        atomic_json(folder / "submission.json", body)
        (folder / "submitted-generator.py").write_bytes(generator.read_bytes())
        (folder / "generator-base.py").write_bytes(
            (directory / "claims" / claims[0]["id"] / "generator-base.py").read_bytes())
        for c in claims:
            atomic_json(directory / "claims" / c["id"] / "job.json", result)
        print("Queued %s (%d classes, one independent verification)" % (result["id"], len(claims)))
        if not args.wait:
            return
        args.id, action = result["id"], "watch"

    if action in ("status", "watch"):
        previous = None
        while True:
            result = api.call("/v1/integration" + ("?id=" + args.id if args.id else ""))
            phases = [(j["id"], j["state"], j["phase"]) for j in result["jobs"]]
            if phases != previous:
                for job in result["jobs"]:
                    print("%s %s | %s | %s" % (job["id"], job["state"], job["phase"], job["unit"]))
                    if job["receipt"]:
                        print(json.dumps(job["receipt"], indent=1))
                previous = phases
            if action == "status" or not result["jobs"] or all(j["state"] in ("accepted", "rejected") for j in result["jobs"]):
                print("Native credits:", json.dumps(result["leaderboard"]))
                api.close()
                if action == "watch":
                    if not result["jobs"] and args.id:
                        raise SystemExit("Native job missing: " + args.id)
                    if any(j["state"] == "rejected" for j in result["jobs"]):
                        raise SystemExit(1)
                return
            time.sleep(2)

    if action == "sync":
        base = api.call("/v1/integration/base")
        current = hashlib.sha256(generator.read_bytes()).hexdigest()
        if current != base["generator"]:
            statuses = {j["id"]: j for j in api.call("/v1/integration")["jobs"]}
            restored = False
            for path in (directory / "jobs").glob("*/submitted-generator.py"):
                if path.parent.name not in statuses or statuses[path.parent.name]["state"] != "accepted":
                    continue
                old = path.with_name("generator-base.py")
                if (hashlib.sha256(path.read_bytes()).hexdigest() == current
                        and hashlib.sha256(old.read_bytes()).hexdigest() == base["generator"]):
                    generator.write_bytes(old.read_bytes())
                    restored = True
                    break
            if not restored:
                raise SystemExit("Generator differs from server; preserve local edits and update before syncing")
        sync_client_baseline(ROOT, base)
        print("Accepted overlays synced:", base["revision"])

