def fmt_duration(seconds):
    """Compact ETA: 45s, 12m, 5h 20m, 3d 4h."""
    seconds = max(0, int(seconds))
    if seconds < 60:
        return "%ds" % seconds
    minutes, seconds = divmod(seconds, 60)
    if minutes < 60:
        return "%dm" % minutes
    hours, minutes = divmod(minutes, 60)
    if hours < 48:
        return "%dh %dm" % (hours, minutes)
    days, hours = divmod(hours, 24)
